["Payday 2’ye hoş geldin!"] = "PAYDAY 2’YE HOŞ GELDİN!",
["Payday Ekspresi"] = "PAYDAY EKSPRESİ",
["Payday Gang bugüne kadar Güney’de pek iş almadı; sınırın güneyini saymıyoruz bile! Ama bu ileride değişirse diye Locke, tozlu ovalarda iyi koruma sağlayacak bu takımlardan bol miktarda stokladı."] = "PAYDAY GANG BUGÜNE KADAR GÜNEY’DE PEK İŞ ALMADI; SINIRIN GÜNEYİNİ SAYMIYORUZ BİLE! AMA BU İLERİDE DEĞİŞİRSE DİYE LOCKE, TOZLU OVALARDA İYİ KORUMA SAĞLAYACAK BU TAKIMLARDAN BOL MİKTARDA STOKLADI.",
["Payday Gang mutlu tatiller diler!"] = "PAYDAY GANG MUTLU TATİLLER DİLER!",
["Payday Gang çok sağlam. Sadece dört kişi lan! Sizinle yerleri sildiklerini duydum!"] = "PAYDAY GANG ÇOK SAĞLAM. SADECE DÖRT KİŞİ LAN! SİZİNLE YERLERİ SİLDİKLERİNİ DUYDUM!",
["Payday Gang şehre geldiğinde GenSec, D.C.’nin en büyük güvenlik şirketiydi ama palyaçolar açamadıkları bir kasayla hiç karşılaşmadı. Çok geçmeden GenSec müşterileri kendilerine sormaya başladı: Hiçbir şeyi güvende tutamayan güvenliğe neden para ödeyelim?"] = "PAYDAY GANG ŞEHRE GELDİĞİNDE GENSEC, D.C.’NİN EN BÜYÜK GÜVENLİK ŞİRKETİYDİ AMA PALYAÇOLAR AÇAMADIKLARI BİR KASAYLA HİÇ KARŞILAŞMADI. ÇOK GEÇMEDEN GENSEC MÜŞTERİLERİ KENDİLERİNE SORMAYA BAŞLADI: HİÇBİR ŞEYİ GÜVENDE TUTAMAYAN GÜVENLİĞE NEDEN PARA ÖDEYELİM?",
["Payday Gang'i tuttuğunuzda en iyileri tutmuş olursunuz."] = "PAYDAY GANG'İ TUTTUĞUNUZDA EN İYİLERİ TUTMUŞ OLURSUNUZ.",
["Payday Gang, rehineyi teslim aldık, ödemenin aktarılmasına izin verdik."] = "PAYDAY GANG, REHİNEYİ TESLİM ALDIK, ÖDEMENİN AKTARILMASINA İZİN VERDİK.",
["Payday Gang, Özel Birimler ve Soygunlar hakkında okumak için FBI dosyalarına göz at."] = "PAYDAY GANG, ÖZEL BİRİMLER VE SOYGUNLAR HAKKINDA OKUMAK İÇİN FBI DOSYALARINA GÖZ AT.",
["Payday Gang’i gammazlarsan bir misilleme beklemelisin. Ekip, parmak sallayıp sertçe azarlamakla yetinmez. Mermi bekleyebilirsin; hem de bolca. Bu baret, eski usul çevik kuvvet teknolojisi: Önü güçlendirilmiş camlı ağır demir. Delip geçmeye çalışana bol şans."] = "PAYDAY GANG’İ GAMMAZLARSAN BİR MİSİLLEME BEKLEMELİSİN. EKİP, PARMAK SALLAYIP SERTÇE AZARLAMAKLA YETİNMEZ. MERMİ BEKLEYEBİLİRSİN; HEM DE BOLCA. BU BARET, ESKİ USUL ÇEVİK KUVVET TEKNOLOJİSİ: ÖNÜ GÜÇLENDİRİLMİŞ CAMLI AĞIR DEMİR. DELİP GEÇMEYE ÇALIŞANA BOL ŞANS.",
["Payday Kumbarası efsanesini duydun mu? Söylentiye göre yılda bir kez Dünya'ya gelir. Ona bol bol Piggy Bucks verirsen karşılığını tatlı mı tatlı DP olarak alırsın!"] = "PAYDAY KUMBARASI EFSANESİNİ DUYDUN MU? SÖYLENTİYE GÖRE YILDA BİR KEZ DÜNYA'YA GELİR. ONA BOL BOL PİGGY BUCKS VERİRSEN KARŞILIĞINI TATLI MI TATLI DP OLARAK ALIRSIN!",
