["Pazarda satılamaz veya takas edilemez."] = "PAZARDA SATILAMAZ VEYA TAKAS EDİLEMEZ.",
["Pazarda satılamaz, takas edilemez veya açılamaz."] = "PAZARDA SATILAMAZ, TAKAS EDİLEMEZ VEYA AÇILAMAZ.",
["Pazarlamacı kadını vitrini kendisinin açmasına da \"ikna\" edebilirsiniz. Anladınız mı?"] = "PAZARLAMACI KADINI VİTRİNİ KENDİSİNİN AÇMASINA DA \"İKNA\" EDEBİLİRSİNİZ. ANLADINIZ MI?",
["Peacemaker .45 Revolveri"] = "PEACEMAKER .45 REVOLVERİ",
["Peacemaker .45 revolveri ile kalçadan ateş ederek, ilk öldürmeden itibaren 6 saniye içinde toplam 6 kolluk görevlisi öldür."] = "PEACEMAKER .45 REVOLVERİ İLE KALÇADAN ATEŞ EDEREK, İLK ÖLDÜRMEDEN İTİBAREN 6 SANİYE İÇİNDE TOPLAM 6 KOLLUK GÖREVLİSİ ÖLDÜR.",
["Peh! Hiç eğlenceli değilsin. Biraz da eğlenemeyeceksek o kadar sikik parayı çalmanın ne anlamı var, ha?"] = "PEH! HİÇ EĞLENCELİ DEĞİLSİN. BİRAZ DA EĞLENEMEYECEKSEK O KADAR SİKİK PARAYI ÇALMANIN NE ANLAMI VAR, HA?",
["Peh! Hiç eğlenceli değilsin. Biraz eğlenemeyeceksek o kadar sikik parayı çalmanın ne anlamı var, ha?"] = "PEH! HİÇ EĞLENCELİ DEĞİLSİN. BİRAZ EĞLENEMEYECEKSEK O KADAR SİKİK PARAYI ÇALMANIN NE ANLAMI VAR, HA?",
["Peh, gözetim bunu göstermemişti. Neyse, geçmelisiniz."] = "PEH, GÖZETİM BUNU GÖSTERMEMİŞTİ. NEYSE, GEÇMELİSİNİZ.",
["Peh, gözetleme görüntülerinde bu yoktu. Neyse, onu aşmalısınız."] = "PEH, GÖZETLEME GÖRÜNTÜLERİNDE BU YOKTU. NEYSE, ONU AŞMALISINIZ.",
["Peh, o teklif sersemlere göre. Kesin daha iyisini yaptırabiliriz. Soğukkanlı kalın dostlar."] = "PEH, O TEKLİF SERSEMLERE GÖRE. KESİN DAHA İYİSİNİ YAPTIRABİLİRİZ. SOĞUKKANLI KALIN DOSTLAR.",
["Pek az plan düşmanla ilk temastan sağ çıkar. Duruma iyi uyum sağladınız ve şiddet konusunda etkileyici bir yetenek sergilediniz. Kazancınızın tadını çıkarın. Ortalık yatışınca sizinle tekrar iletişime geçeceğim."] = "PEK AZ PLAN DÜŞMANLA İLK TEMASTAN SAĞ ÇIKAR. DURUMA İYİ UYUM SAĞLADINIZ VE ŞİDDET KONUSUNDA ETKİLEYİCİ BİR YETENEK SERGİLEDİNİZ. KAZANCINIZIN TADINI ÇIKARIN. ORTALIK YATIŞINCA SİZİNLE TEKRAR İLETİŞİME GEÇECEĞİM.",
["Pek bilinmeyen bir gerçek: Bile, 1. Dünya Savaşı’nın hava muharebelerine hayran! Dikkatli gözler, soygunlarda onu sık sık aslına uygun avcı pilotu üniformasıyla, helikopter yerine bir Avro 504 uçurduğunu hayal ederken yakalar. Gökten ölüm yağdırmak isteyen?"] = "PEK BİLİNMEYEN BİR GERÇEK: BILE, 1. DÜNYA SAVAŞI’NIN HAVA MUHAREBELERİNE HAYRAN! DİKKATLİ GÖZLER, SOYGUNLARDA ONU SIK SIK ASLINA UYGUN AVCI PİLOTU ÜNİFORMASIYLA, HELİKOPTER YERİNE BİR AVRO 504 UÇURDUĞUNU HAYAL EDERKEN YAKALAR. GÖKTEN ÖLÜM YAĞDIRMAK İSTEYEN?",
["Pek bilinmeyen bir gerçek: Duke üniversitede arkeoloji okudu ama suç hayatına başladıktan sonra profesör olma yolundan vazgeçti."] = "PEK BİLİNMEYEN BİR GERÇEK: DUKE ÜNİVERSİTEDE ARKEOLOJİ OKUDU AMA SUÇ HAYATINA BAŞLADIKTAN SONRA PROFESÖR OLMA YOLUNDAN VAZGEÇTİ.",
["Pek güzel değil. Büyük bir başarı da sayılmaz. Ama sağ çıktığınız her gün kazançtır. "] = "PEK GÜZEL DEĞİL. BÜYÜK BİR BAŞARI DA SAYILMAZ. AMA SAĞ ÇIKTIĞINIZ HER GÜN KAZANÇTIR. ",
["Pek ince davranmıyorsunuz. Geliyorum!"] = "PEK İNCE DAVRANMIYORSUNUZ. GELİYORUM!",
["Pek iyi görünmüyor! Devam edin!"] = "PEK İYİ GÖRÜNMÜYOR! DEVAM EDİN!",
["Pek iyi hissetmiyorum..."] = "PEK İYİ HİSSETMİYORUM...",
["Pek parlakmış. Satmaya neredeyse kıyamayacağım ama önce buradan çıkarmamız gerek!"] = "PEK PARLAKMIŞ. SATMAYA NEREDEYSE KIYAMAYACAĞIM AMA ÖNCE BURADAN ÇIKARMAMIZ GEREK!",
["Pek sık kusursuz demem ama şimdi diyorum. İyi iş."] = "PEK SIK KUSURSUZ DEMEM AMA ŞİMDİ DİYORUM. İYİ İŞ.",
["Pek çok adı olan kişi"] = "PEK ÇOK ADI OLAN KİŞİ",
["Pek çok yönden sıradan bir hırsızsın. Cep boşaltır, kasadan çalarsın. Hayatı kocaman bir sayı oyunu olarak görürsün. Ama sende şöyle bir şey var: Zekisin. Ceplerin kendiliğinden boşalmasını sağlamayı çözdün. Tek bir yasayı çiğnemeden kasaları kurutmayı öğrendin. O sayı oyununa gelince; açık farkla kazanıyorsun. Şirketler dünyası bir suçlunun oyun alanıdır; emekle kazandığın başarının sırrı bu. Yani hayır, sıradan bir hırsız değilsin. Olağanüstü bir hırsızsın."] = "PEK ÇOK YÖNDEN SIRADAN BİR HIRSIZSIN. CEP BOŞALTIR, KASADAN ÇALARSIN. HAYATI KOCAMAN BİR SAYI OYUNU OLARAK GÖRÜRSÜN. AMA SENDE ŞÖYLE BİR ŞEY VAR: ZEKİSİN. CEPLERİN KENDİLİĞİNDEN BOŞALMASINI SAĞLAMAYI ÇÖZDÜN. TEK BİR YASAYI ÇİĞNEMEDEN KASALARI KURUTMAYI ÖĞRENDİN. O SAYI OYUNUNA GELİNCE; AÇIK FARKLA KAZANIYORSUN. ŞİRKETLER DÜNYASI BİR SUÇLUNUN OYUN ALANIDIR; EMEKLE KAZANDIĞIN BAŞARININ SIRRI BU. YANİ HAYIR, SIRADAN BİR HIRSIZ DEĞİLSİN. OLAĞANÜSTÜ BİR HIRSIZSIN.",
["Pek çoğunun ötesinde, çoğunun erişemeyeceği yerde. Ulaştığın nokta bu; başardıkların bunlar. Bu seviyedeki bir soyguncuya ne verilir? Bu süs setiyle mutlaka iz bırakacaksın."] = "PEK ÇOĞUNUN ÖTESİNDE, ÇOĞUNUN ERİŞEMEYECEĞİ YERDE. ULAŞTIĞIN NOKTA BU; BAŞARDIKLARIN BUNLAR. BU SEVİYEDEKİ BİR SOYGUNCUYA NE VERİLİR? BU SÜS SETİYLE MUTLAKA İZ BIRAKACAKSIN.",
["Peki Vernon. Gemma, çok iyi Teksas aksanı yaptığını söylüyor. Duymayı çok isterim."] = "PEKİ VERNON. GEMMA, ÇOK İYİ TEKSAS AKSANI YAPTIĞINI SÖYLÜYOR. DUYMAYI ÇOK İSTERİM.",
["Peki Vlad. Avustralya kaplan yılanıyla karşılaşmamı hiç anlatmış mıydım?"] = "PEKİ VLAD. AVUSTRALYA KAPLAN YILANIYLA KARŞILAŞMAMI HİÇ ANLATMIŞ MIYDIM?",
["Peki Vlad... Hiç Çince biliyor musun?"] = "PEKİ VLAD... HİÇ ÇİNCE BİLİYOR MUSUN?",
["Peki fiyatı? 18 dolar. Nasıl ama, ha?"] = "PEKİ FİYATI? 18 DOLAR. NASIL AMA, HA?",
["Peki millet, o dizüstü bilgisayar nerede?"] = "PEKİ MİLLET, O DİZÜSTÜ BİLGİSAYAR NEREDE?",
["Peki sence ne yapmalıyım?"] = "PEKİ SENCE NE YAPMALIYIM?",
["Peki siz...? Söylemeseniz iyi olur. Ne kadar az bilirsem, bilirsiniz işte. Hadi."] = "PEKİ SİZ...? SÖYLEMESENİZ İYİ OLUR. NE KADAR AZ BİLİRSEM, BİLİRSİNİZ İŞTE. HADİ.",
["Peki size kaça mal olacak? Şöyle diyelim... 18 dolar?"] = "PEKİ SİZE KAÇA MAL OLACAK? ŞÖYLE DİYELİM... 18 DOLAR?",
["Peki ya kocaman alevli patlamalar?"] = "PEKİ YA KOCAMAN ALEVLİ PATLAMALAR?",
["Peki, işi bitirmeye hazır mısınız? İçerideki adamımızı bulun. Size sıvışabileceğiniz bir yol gösterecek."] = "PEKİ, İŞİ BİTİRMEYE HAZIR MISINIZ? İÇERİDEKİ ADAMIMIZI BULUN. SİZE SIVIŞABİLECEĞİNİZ BİR YOL GÖSTERECEK.",
["Peki, keçi nasıl ses çıkarır?"] = "PEKİ, KEÇİ NASIL SES ÇIKARIR?",
["Peki, tamam. Doğru duyduysam Boogers adlı salata barını almak için krediye hayır diyorsunuz, öyle mi?"] = "PEKİ, TAMAM. DOĞRU DUYDUYSAM BOOGERS ADLI SALATA BARINI ALMAK İÇİN KREDİYE HAYIR DİYORSUNUZ, ÖYLE Mİ?",
["Peki, şu Payday elemanları hakkında gerçekten ne biliyorsun? Bu bokun bizim yüzümüzden çıktığını sanmıyorum."] = "PEKİ, ŞU PAYDAY ELEMANLARI HAKKINDA GERÇEKTEN NE BİLİYORSUN? BU BOKUN BİZİM YÜZÜMÜZDEN ÇIKTIĞINI SANMIYORUM.",
["Peki, şu anda bu odada bulunan herhangi biri bana Birleşik Devletler'e karşı vatana ihanet eylemlerine ilişkin bir anayasa hükmü söyleyebilir mi? Kimse var mı? Anayasa'nın 3. maddesinin 3. bölümü şöyle der: \"Birleşik Devletler'e ihanet, ancak onlara karşı savaş açmak veya düşmanlarının tarafını tutup onlara yardım ve destek sağlamakla gerçekleşir. Hiç kimse, aynı açık eyleme ilişkin iki tanığın ifadesi veya...? ...veya...? Tamamlamak isteyen var mı? Kimse?... Bueller?"] = "PEKİ, ŞU ANDA BU ODADA BULUNAN HERHANGİ BİRİ BANA BİRLEŞİK DEVLETLER'E KARŞI VATANA İHANET EYLEMLERİNE İLİŞKİN BİR ANAYASA HÜKMÜ SÖYLEYEBİLİR Mİ? KİMSE VAR MI? ANAYASA'NIN 3. MADDESİNİN 3. BÖLÜMÜ ŞÖYLE DER: \"BİRLEŞİK DEVLETLER'E İHANET, ANCAK ONLARA KARŞI SAVAŞ AÇMAK VEYA DÜŞMANLARININ TARAFINI TUTUP ONLARA YARDIM VE DESTEK SAĞLAMAKLA GERÇEKLEŞİR. HİÇ KİMSE, AYNI AÇIK EYLEME İLİŞKİN İKİ TANIĞIN İFADESİ VEYA...? ...VEYA...? TAMAMLAMAK İSTEYEN VAR MI? KİMSE?... BUELLER?",
["Peki. Evet. Tamam, işte burada. 8394. Kimseyle paylaşma, tamam mı?"] = "PEKİ. EVET. TAMAM, İŞTE BURADA. 8394. KİMSEYLE PAYLAŞMA, TAMAM MI?",
["Peki. Tamam. Emin misin? Muzların daha az muza benzemesi için bir kampanyaya yatırım yapmak istemiyor musun?"] = "PEKİ. TAMAM. EMİN MİSİN? MUZLARIN DAHA AZ MUZA BENZEMESİ İÇİN BİR KAMPANYAYA YATIRIM YAPMAK İSTEMİYOR MUSUN?",
["Peki. Tamam. Köprü şimdi geri dönüyor. Ama birkaç dakika sürecek. Hayatta kalın ekip!"] = "PEKİ. TAMAM. KÖPRÜ ŞİMDİ GERİ DÖNÜYOR. AMA BİRKAÇ DAKİKA SÜRECEK. HAYATTA KALIN EKİP!",
["Pekiii, sıradaki adım..."] = "PEKİİİ, SIRADAKİ ADIM...",
["Pekiii, çark keskin nişancıda durdu... "] = "PEKİİİ, ÇARK KESKİN NİŞANCIDA DURDU... ",
["Pekâlâ Broadsword. Tamam, kapatıyorum."] = "PEKÂLÂ BROADSWORD. TAMAM, KAPATIYORUM.",
["Pekâlâ Dallas. Dün gece çaldığımız erişim kodlarını kullanma vakti. Binaya girmenin yolunu bul, polis veritabanına eriş ve Crime.net hakkında tuttukları bütün bilgileri sil. Parkta yürüyüş olmayacak. Hâlâ formunda olduğunu göster."] = "PEKÂLÂ DALLAS. DÜN GECE ÇALDIĞIMIZ ERİŞİM KODLARINI KULLANMA VAKTİ. BİNAYA GİRMENİN YOLUNU BUL, POLİS VERİTABANINA ERİŞ VE CRIME.NET HAKKINDA TUTTUKLARI BÜTÜN BİLGİLERİ SİL. PARKTA YÜRÜYÜŞ OLMAYACAK. HÂLÂ FORMUNDA OLDUĞUNU GÖSTER.",
["Pekâlâ Dallas. Dün gece çaldığımız erişim şifrelerini kullanma zamanı. Binaya girmenin bir yolunu bul; polis veri tabanına eriş ve Crime.net hakkında ellerindeki tüm istihbaratı sil. Çocuk oyuncağı olmayacak; gereken yeteneğe hâlâ sahip olduğunu göster."] = "PEKÂLÂ DALLAS. DÜN GECE ÇALDIĞIMIZ ERİŞİM ŞİFRELERİNİ KULLANMA ZAMANI. BİNAYA GİRMENİN BİR YOLUNU BUL; POLİS VERİ TABANINA ERİŞ VE CRIME.NET HAKKINDA ELLERİNDEKİ TÜM İSTİHBARATI SİL. ÇOCUK OYUNCAĞI OLMAYACAK; GEREKEN YETENEĞE HÂLÂ SAHİP OLDUĞUNU GÖSTER.",
["Pekâlâ Kızlar ve Oğlanlar"] = "PEKÂLÂ KIZLAR VE OĞLANLAR",
["Pekâlâ beyler, dinleyin; iyi ve kötü haberlerim var:"] = "PEKÂLÂ BEYLER, DİNLEYİN; İYİ VE KÖTÜ HABERLERİM VAR:",
["Pekâlâ dallamalar, buna hazır mısınız?"] = "PEKÂLÂ DALLAMALAR, BUNA HAZIR MISINIZ?",
["Pekâlâ dostlar. Güzel ve sessizce, tamam mı? İlk iş güvenliği geçmek. Kapıya gidip engellere bir bakın."] = "PEKÂLÂ DOSTLAR. GÜZEL VE SESSİZCE, TAMAM MI? İLK İŞ GÜVENLİĞİ GEÇMEK. KAPIYA GİDİP ENGELLERE BİR BAKIN.",
["Pekâlâ dostlar. Söylenen dükkân bu olmalı. Triad şimdiye kadar gerçek amacını heriflerden saklayabilmiş."] = "PEKÂLÂ DOSTLAR. SÖYLENEN DÜKKÂN BU OLMALI. TRİAD ŞİMDİYE KADAR GERÇEK AMACINI HERİFLERDEN SAKLAYABİLMİŞ.",
["Pekâlâ dostlarım, artık orada istenmiyorsunuz gibi. Twitch yolda. Yakında gelir."] = "PEKÂLÂ DOSTLARIM, ARTIK ORADA İSTENMİYORSUNUZ GİBİ. TWITCH YOLDA. YAKINDA GELİR.",
["Pekâlâ dostlarım, sizi işinizle baş başa bırakma vaktim geldi. Yapacak çok iş var malum. Kozak ve Simmons'a en içten selamlar!"] = "PEKÂLÂ DOSTLARIM, SİZİ İŞİNİZLE BAŞ BAŞA BIRAKMA VAKTİM GELDİ. YAPACAK ÇOK İŞ VAR MALUM. KOZAK VE SİMMONS'A EN İÇTEN SELAMLAR!",
["Pekâlâ millet, Hector'la konuştum. Mendoza'nın ileri gelenleri ülkeden kaçıyor ama Hector henüz gitmelerine razı değil. Nereye gittiklerini öğrenmek istiyor. İçlerindeki bir köstebek onları Cobras sokak çetesine satmış. Öyle azılı pislikler ki Hector'ın adamları bile onlarla iş yapmıyor. Siz burada devreye giriyorsunuz... Bilgi karşılığında onlarla metamfetamin takası yapın."] = "PEKÂLÂ MİLLET, HECTOR'LA KONUŞTUM. MENDOZA'NIN İLERİ GELENLERİ ÜLKEDEN KAÇIYOR AMA HECTOR HENÜZ GİTMELERİNE RAZI DEĞİL. NEREYE GİTTİKLERİNİ ÖĞRENMEK İSTİYOR. İÇLERİNDEKİ BİR KÖSTEBEK ONLARI COBRAS SOKAK ÇETESİNE SATMIŞ. ÖYLE AZILI PİSLİKLER Kİ HECTOR'IN ADAMLARI BİLE ONLARLA İŞ YAPMIYOR. SİZ BURADA DEVREYE GİRİYORSUNUZ... BİLGİ KARŞILIĞINDA ONLARLA METAMFETAMİN TAKASI YAPIN.",
["Pekâlâ millet, bu güzel bir fırsat. Vitrinlerde çeşit çeşit orta kalite elmas falan var. Hünerinizi gösterin, kendinizi kanıtlayın, sonra çıkın. Klasik bir soygun."] = "PEKÂLÂ MİLLET, BU GÜZEL BİR FIRSAT. VİTRİNLERDE ÇEŞİT ÇEŞİT ORTA KALİTE ELMAS FALAN VAR. HÜNERİNİZİ GÖSTERİN, KENDİNİZİ KANITLAYIN, SONRA ÇIKIN. KLASİK BİR SOYGUN.",
["Pekâlâ o zaman. Ne dilediğinize dikkat edin be."] = "PEKÂLÂ O ZAMAN. NE DİLEDİĞİNİZE DİKKAT EDİN BE.",
["Pekâlâ sevgili dostlarım. Operasyonun değmesi için yeterince ganimet topladık. Devam edip etmemek size kalmış. Fazladan her dolar, rand ve ruble dostluğumuzu güçlendirir, ha? Kesinlikle."] = "PEKÂLÂ SEVGİLİ DOSTLARIM. OPERASYONUN DEĞMESİ İÇİN YETERİNCE GANİMET TOPLADIK. DEVAM EDİP ETMEMEK SİZE KALMIŞ. FAZLADAN HER DOLAR, RAND VE RUBLE DOSTLUĞUMUZU GÜÇLENDİRİR, HA? KESİNLİKLE.",
["Pekâlâ! Bahçe hortumunu bulun!"] = "PEKÂLÂ! BAHÇE HORTUMUNU BULUN!",
["Pekâlâ, Vlad iş yapış tarzını beğeniyor. Sana bir işi olduğunu söylüyor. Özel bir iş. Büyük bir iş. Böyle bir şey herkesin başına yalnızca bela açar. O yüzden sert ve hızlı vurduğundan emin ol."] = "PEKÂLÂ, VLAD İŞ YAPIŞ TARZINI BEĞENİYOR. SANA BİR İŞİ OLDUĞUNU SÖYLÜYOR. ÖZEL BİR İŞ. BÜYÜK BİR İŞ. BÖYLE BİR ŞEY HERKESİN BAŞINA YALNIZCA BELA AÇAR. O YÜZDEN SERT VE HIZLI VURDUĞUNDAN EMİN OL.",
["Pekâlâ, Vlad iş yapış tarzını beğeniyor. Sana bir işi olduğunu söylüyor. Özel bir iş. Büyük bir iş. Gage için bastığın o Murkywater deposundan \"bir şey\" çalmanı istiyor, hatırladın mı? Vlad, Murky tayfasına karşı oynuyor. Böyle bir şey herkesin başına yalnızca bela açar. O yüzden sert ve hızlı vurduğundan emin ol."] = "PEKÂLÂ, VLAD İŞ YAPIŞ TARZINI BEĞENİYOR. SANA BİR İŞİ OLDUĞUNU SÖYLÜYOR. ÖZEL BİR İŞ. BÜYÜK BİR İŞ. GAGE İÇİN BASTIĞIN O MURKYWATER DEPOSUNDAN \"BİR ŞEY\" ÇALMANI İSTİYOR, HATIRLADIN MI? VLAD, MURKY TAYFASINA KARŞI OYNUYOR. BÖYLE BİR ŞEY HERKESİN BAŞINA YALNIZCA BELA AÇAR. O YÜZDEN SERT VE HIZLI VURDUĞUNDAN EMİN OL.",
["Pekâlâ, aldınız. Şimdi ağaca koyun."] = "PEKÂLÂ, ALDINIZ. ŞİMDİ AĞACA KOYUN.",
["Pekâlâ, ana kodu alma vakti. CFO'da olacak."] = "PEKÂLÂ, ANA KODU ALMA VAKTİ. CFO'DA OLACAK.",
["Pekâlâ, aradığımızı aldık. Kaçabilir ya da geri dönüp The Grin'i temizleyebilirsiniz."] = "PEKÂLÂ, ARADIĞIMIZI ALDIK. KAÇABİLİR YA DA GERİ DÖNÜP THE GRIN'İ TEMİZLEYEBİLİRSİNİZ.",
["Pekâlâ, bakalım..."] = "PEKÂLÂ, BAKALIM...",
["Pekâlâ, başlıyoruz. O Kataru aptalları Bain’imizi fazla uzun süre ellerinde tuttu. Elephant’ın sağladığı bilgilerle Bain’in tutulduğu yeri buldum. Murkywater’ın pek çok tesisi var; bu en kötülerinden biri. Deniz feneri olan küçük bir adada, 70’lerde ABD ordusundan aldıkları döküntü bir hapishane. Fener çalıştığı sürece kimse dikkat etmiyor çünkü Murky tayfası burayı bir altyapı hizmetleri iştiraki üzerinden işletiyor. Hapishane, Pearl Harbor’dan sonra Japon savaş esirlerini tutmak için kullanılmış ve gelişmiş tıbbi tesislerle donatılmış. Murky’deyken burada çok kötü deneyler yaptıkları söylenirdi. Sizi içeri sokup Bain’i çıkaracak bir plan üzerinde çalışıyorum. Umarım çok geç kalmamışızdır."] = "PEKÂLÂ, BAŞLIYORUZ. O KATARU APTALLARI BAIN’İMİZİ FAZLA UZUN SÜRE ELLERİNDE TUTTU. ELEPHANT’IN SAĞLADIĞI BİLGİLERLE BAIN’İN TUTULDUĞU YERİ BULDUM. MURKYWATER’IN PEK ÇOK TESİSİ VAR; BU EN KÖTÜLERİNDEN BİRİ. DENİZ FENERİ OLAN KÜÇÜK BİR ADADA, 70’LERDE ABD ORDUSUNDAN ALDIKLARI DÖKÜNTÜ BİR HAPİSHANE. FENER ÇALIŞTIĞI SÜRECE KİMSE DİKKAT ETMİYOR ÇÜNKÜ MURKY TAYFASI BURAYI BİR ALTYAPI HİZMETLERİ İŞTİRAKİ ÜZERİNDEN İŞLETİYOR. HAPİSHANE, PEARL HARBOR’DAN SONRA JAPON SAVAŞ ESİRLERİNİ TUTMAK İÇİN KULLANILMIŞ VE GELİŞMİŞ TIBBİ TESİSLERLE DONATILMIŞ. MURKY’DEYKEN BURADA ÇOK KÖTÜ DENEYLER YAPTIKLARI SÖYLENİRDİ. SİZİ İÇERİ SOKUP BAIN’İ ÇIKARACAK BİR PLAN ÜZERİNDE ÇALIŞIYORUM. UMARIM ÇOK GEÇ KALMAMIŞIZDIR.",
["Pekâlâ, beklerken işi ilerletmek isterseniz çatıya çıkabilirsiniz. Oraya bir çelik halat kurmanız gerek."] = "PEKÂLÂ, BEKLERKEN İŞİ İLERLETMEK İSTERSENİZ ÇATIYA ÇIKABİLİRSİNİZ. ORAYA BİR ÇELİK HALAT KURMANIZ GEREK.",
["Pekâlâ, bence artık patlatmanın vakti geldi. Maskelerinizi takın!"] = "PEKÂLÂ, BENCE ARTIK PATLATMANIN VAKTİ GELDİ. MASKELERİNİZİ TAKIN!",
["Pekâlâ, bildiklerimiz şu: OVERKILL MC bir şekilde beyin-bilgisayar arayüzü denen yeni bir teknolojiyi ele geçirdi. İnanın beyler, gelecek bu. BCI teknolojisi askerî bir insansız hava aracını yalnızca beyninizle kontrol etmenizi sağlıyor; tahmin edebileceğiniz gibi çok değerli. Bain, bunu ele geçirmek için büyük para teklif eden olası bir alıcıyla görüşüyor. BCI başlığı ve bilgisayar yazılımı bir yük treninde yola çıktı bile. Neyse ki Bile sizi bırakmaya hazır. Şimdi işe koyulun."] = "PEKÂLÂ, BİLDİKLERİMİZ ŞU: OVERKILL MC BİR ŞEKİLDE BEYİN-BİLGİSAYAR ARAYÜZÜ DENEN YENİ BİR TEKNOLOJİYİ ELE GEÇİRDİ. İNANIN BEYLER, GELECEK BU. BCI TEKNOLOJİSİ ASKERÎ BİR İNSANSIZ HAVA ARACINI YALNIZCA BEYNİNİZLE KONTROL ETMENİZİ SAĞLIYOR; TAHMİN EDEBİLECEĞİNİZ GİBİ ÇOK DEĞERLİ. BAIN, BUNU ELE GEÇİRMEK İÇİN BÜYÜK PARA TEKLİF EDEN OLASI BİR ALICIYLA GÖRÜŞÜYOR. BCI BAŞLIĞI VE BİLGİSAYAR YAZILIMI BİR YÜK TRENİNDE YOLA ÇIKTI BİLE. NEYSE Kİ BILE SİZİ BIRAKMAYA HAZIR. ŞİMDİ İŞE KOYULUN.",
["Pekâlâ, bir süredir bunu inceliyorum ama hazır olduğumuzdan emin olmam gerekiyordu. First World Bank. Eski, köklü, sırlar ve altınlarla dolu; hepsi alınmayı bekliyor. Zaten ünlüyüz ama bu iş bizi tarih kitaplarına geçirecek."] = "PEKÂLÂ, BİR SÜREDİR BUNU İNCELİYORUM AMA HAZIR OLDUĞUMUZDAN EMİN OLMAM GEREKİYORDU. FIRST WORLD BANK. ESKİ, KÖKLÜ, SIRLAR VE ALTINLARLA DOLU; HEPSİ ALINMAYI BEKLİYOR. ZATEN ÜNLÜYÜZ AMA BU İŞ BİZİ TARİH KİTAPLARINA GEÇİRECEK.",
["Pekâlâ, biraz gürültü koparalım!"] = "PEKÂLÂ, BİRAZ GÜRÜLTÜ KOPARALIM!",
["Pekâlâ, bu Gage'i mutlu eder. Artık paraya çevirebilir ya da fazlası için kalabilirsiniz."] = "PEKÂLÂ, BU GAGE'İ MUTLU EDER. ARTIK PARAYA ÇEVİREBİLİR YA DA FAZLASI İÇİN KALABİLİRSİNİZ.",
["Pekâlâ, bu iş olabilir. Ama hazırlık önemli. Sen profesyonelsin. İşe uygun ekipman gerekir. Şu anda dolaplarda fazla bir şey olmayabilir ama soygun yapıp kötü şöhret kazandıkça o rafları ve dolapları doğru ekipmanla dolduracağız."] = "PEKÂLÂ, BU İŞ OLABİLİR. AMA HAZIRLIK ÖNEMLİ. SEN PROFESYONELSİN. İŞE UYGUN EKİPMAN GEREKİR. ŞU ANDA DOLAPLARDA FAZLA BİR ŞEY OLMAYABİLİR AMA SOYGUN YAPIP KÖTÜ ŞÖHRET KAZANDIKÇA O RAFLARI VE DOLAPLARI DOĞRU EKİPMANLA DOLDURACAĞIZ.",
["Pekâlâ, bu web sayfasında... Az önce ne eklediniz? Pekâlâ. Tamam, tamam."] = "PEKÂLÂ, BU WEB SAYFASINDA... AZ ÖNCE NE EKLEDİNİZ? PEKÂLÂ. TAMAM, TAMAM.",
["Pekâlâ, bunu da hallettiğimize göre sunucu odasını bulma zamanı."] = "PEKÂLÂ, BUNU DA HALLETTİĞİMİZE GÖRE SUNUCU ODASINI BULMA ZAMANI.",
["Pekâlâ, burası. Unutma, erişim kodları için buradayız."] = "PEKÂLÂ, BURASI. UNUTMA, ERİŞİM KODLARI İÇİN BURADAYIZ.",
["Pekâlâ, evi görüyor musunuz? İçeri girin. Muhafızlara ve kameralara dikkat edin."] = "PEKÂLÂ, EVİ GÖRÜYOR MUSUNUZ? İÇERİ GİRİN. MUHAFIZLARA VE KAMERALARA DİKKAT EDİN.",
["Pekâlâ, evi görüyor musunuz? İçeri girip sunucu odasını bulun. Laboratuvara ulaşmak için güvenlik sistemini ele geçirmemiz gerek."] = "PEKÂLÂ, EVİ GÖRÜYOR MUSUNUZ? İÇERİ GİRİP SUNUCU ODASINI BULUN. LABORATUVARA ULAŞMAK İÇİN GÜVENLİK SİSTEMİNİ ELE GEÇİRMEMİZ GEREK.",
["Pekâlâ, geri dönüp o cesedi ortadan kaldır."] = "PEKÂLÂ, GERİ DÖNÜP O CESEDİ ORTADAN KALDIR.",
["Pekâlâ, gidip şu işi yapalım da akşam yemeği yiyebileyim."] = "PEKÂLÂ, GİDİP ŞU İŞİ YAPALIM DA AKŞAM YEMEĞİ YİYEBİLEYİM.",
["Pekâlâ, giriş noktasındayız. İşaretimle aynı anda... Şimdi."] = "PEKÂLÂ, GİRİŞ NOKTASINDAYIZ. İŞARETİMLE AYNI ANDA... ŞİMDİ.",
["Pekâlâ, insanların seni izlediğini daha önce söylemiştim. Özellikle bir adam seninle ilgileniyor. Bu yeni bağlantıyla büyük bir işimiz olabilir ama aklındaki iş zor olacak. Hazırlanmalısın."] = "PEKÂLÂ, İNSANLARIN SENİ İZLEDİĞİNİ DAHA ÖNCE SÖYLEMİŞTİM. ÖZELLİKLE BİR ADAM SENİNLE İLGİLENİYOR. BU YENİ BAĞLANTIYLA BÜYÜK BİR İŞİMİZ OLABİLİR AMA AKLINDAKİ İŞ ZOR OLACAK. HAZIRLANMALISIN.",
["Pekâlâ, isteği onaylayın yeter. Hay sikeyim, işi ne kolaymış."] = "PEKÂLÂ, İSTEĞİ ONAYLAYIN YETER. HAY SİKEYİM, İŞİ NE KOLAYMIŞ.",
["Pekâlâ, içeri girip sizi almaktan başka seçenek bırakmadınız. Bu işi zor yoldan yapacağız."] = "PEKÂLÂ, İÇERİ GİRİP SİZİ ALMAKTAN BAŞKA SEÇENEK BIRAKMADINIZ. BU İŞİ ZOR YOLDAN YAPACAĞIZ.",
["Pekâlâ, içeri girip tacı bulun."] = "PEKÂLÂ, İÇERİ GİRİP TACI BULUN.",
["Pekâlâ, işe koyulma vakti."] = "PEKÂLÂ, İŞE KOYULMA VAKTİ.",
["Pekâlâ, işlem başladı, pişiyor. Hector aracılığıyla bir uzmanla bağlantım var. Size yol göstereceğim."] = "PEKÂLÂ, İŞLEM BAŞLADI, PİŞİYOR. HECTOR ARACILIĞIYLA BİR UZMANLA BAĞLANTIM VAR. SİZE YOL GÖSTERECEĞİM.",
["Pekâlâ, kameralar bizi gördü. B planına geçmeliyiz."] = "PEKÂLÂ, KAMERALAR BİZİ GÖRDÜ. B PLANINA GEÇMELİYİZ.",
["Pekâlâ, kıpırdamayın."] = "PEKÂLÂ, KIPIRDAMAYIN.",
["Pekâlâ, minibüs sizi burada bırakacak."] = "PEKÂLÂ, MİNİBÜS SİZİ BURADA BIRAKACAK.",
["Pekâlâ, o zaman diğer yolu seçelim. Gürültü koparın dostlar."] = "PEKÂLÂ, O ZAMAN DİĞER YOLU SEÇELİM. GÜRÜLTÜ KOPARIN DOSTLAR.",
["Pekâlâ, sadece sizi geri aramaları gerek. Ne kadar hızlı, o kadar iyi."] = "PEKÂLÂ, SADECE SİZİ GERİ ARAMALARI GEREK. NE KADAR HIZLI, O KADAR İYİ.",
["Pekâlâ, sunucu odasını bulup girin. Artık alarmları kapatmanın anlamı yok."] = "PEKÂLÂ, SUNUCU ODASINI BULUP GİRİN. ARTIK ALARMLARI KAPATMANIN ANLAMI YOK.",
["Pekâlâ, sıradaki adım..."] = "PEKÂLÂ, SIRADAKİ ADIM...",
["Pekâlâ, tekrar edeyim: Taxman, IRS'te çalışıyor ve büyük bir şirketle karanlık bir anlaşma yapıyor."] = "PEKÂLÂ, TEKRAR EDEYİM: TAXMAN, IRS'TE ÇALIŞIYOR VE BÜYÜK BİR ŞİRKETLE KARANLIK BİR ANLAŞMA YAPIYOR.",
["Pekâlâ, termit şimdiye kadar yarılanmış olmalı. Devam edin, beyler."] = "PEKÂLÂ, TERMİT ŞİMDİYE KADAR YARILANMIŞ OLMALI. DEVAM EDİN, BEYLER.",
["Pekâlâ, yeni bir bağlantımız var. Kendine The Elephant diyen bir siyasetçi. İş biraz endüstriyel sabotaj. Çok parlak bir bilim insanı soğuk füzyonu çözmüş. Petrol şirketlerini diskoyla aynı mezara sokacak türden teknoloji. İktidar sahiplerinin de o şirketlerde çok parası var. Bu yüzden The Elephant ve dostları teknolojinin gömüldüğünden emin olmak istiyor. Bana uyar."] = "PEKÂLÂ, YENİ BİR BAĞLANTIMIZ VAR. KENDİNE THE ELEPHANT DİYEN BİR SİYASETÇİ. İŞ BİRAZ ENDÜSTRİYEL SABOTAJ. ÇOK PARLAK BİR BİLİM İNSANI SOĞUK FÜZYONU ÇÖZMÜŞ. PETROL ŞİRKETLERİNİ DİSKOYLA AYNI MEZARA SOKACAK TÜRDEN TEKNOLOJİ. İKTİDAR SAHİPLERİNİN DE O ŞİRKETLERDE ÇOK PARASI VAR. BU YÜZDEN THE ELEPHANT VE DOSTLARI TEKNOLOJİNİN GÖMÜLDÜĞÜNDEN EMİN OLMAK İSTİYOR. BANA UYAR.",
["Pekâlâ, yeniden girdim."] = "PEKÂLÂ, YENİDEN GİRDİM.",
["Pekâlâ, zarar yoksa sorun da yok. Silahları alıp çıkalım buradan."] = "PEKÂLÂ, ZARAR YOKSA SORUN DA YOK. SİLAHLARI ALIP ÇIKALIM BURADAN.",
["Pekâlâ, çıkışımız bu. Yukarı dönüp bitişik binaya açılan duvara C4 koyun."] = "PEKÂLÂ, ÇIKIŞIMIZ BU. YUKARI DÖNÜP BİTİŞİK BİNAYA AÇILAN DUVARA C4 KOYUN.",
["Pekâlâ, şimdi şunu bir halledeyim. Hemen biter."] = "PEKÂLÂ, ŞİMDİ ŞUNU BİR HALLEDEYİM. HEMEN BİTER.",
["Pekâlâ, şimdi şunu bir halledeyim. Öyle hemen olmayacak."] = "PEKÂLÂ, ŞİMDİ ŞUNU BİR HALLEDEYİM. ÖYLE HEMEN OLMAYACAK.",
["Pekâlâ. Aramayı bağlayın. Federallerle ben konuşayım."] = "PEKÂLÂ. ARAMAYI BAĞLAYIN. FEDERALLERLE BEN KONUŞAYIM.",
["Pekâlâ. Ben helikopteri hazırlayacağım. Siz radar çanaklarıyla ilgileneceksiniz. Anlaştık mı?"] = "PEKÂLÂ. BEN HELİKOPTERİ HAZIRLAYACAĞIM. SİZ RADAR ÇANAKLARIYLA İLGİLENECEKSİNİZ. ANLAŞTIK MI?",
["Pekâlâ. Federallerin elinde sana karşı bir şey yok. Masken var. Silahların var. Peki Payday Gang adını efsaneleştirmek için gerekenlere sahip misin? Öğrenmenin zamanı geldi. DC’nin her yanında banka şubeleri ve kuyumcular var. Soyulmayalı uzun zaman oldu. Fazla uzun. Hadi zengin olalım."] = "PEKÂLÂ. FEDERALLERİN ELİNDE SANA KARŞI BİR ŞEY YOK. MASKEN VAR. SİLAHLARIN VAR. PEKİ PAYDAY GANG ADINI EFSANELEŞTİRMEK İÇİN GEREKENLERE SAHİP MİSİN? ÖĞRENMENİN ZAMANI GELDİ. DC’NİN HER YANINDA BANKA ŞUBELERİ VE KUYUMCULAR VAR. SOYULMAYALI UZUN ZAMAN OLDU. FAZLA UZUN. HADİ ZENGİN OLALIM.",
["Pekâlâ. Karşıdaki ofisten geçin, sonra aşağı inin. Hadi, çıkın buradan."] = "PEKÂLÂ. KARŞIDAKİ OFİSTEN GEÇİN, SONRA AŞAĞI İNİN. HADİ, ÇIKIN BURADAN.",
["Pekâlâ. Kod. İlk aklıma gelen, muhtemelen birinin e-postasında olduğudur. Bir terminal bulup girin."] = "PEKÂLÂ. KOD. İLK AKLIMA GELEN, MUHTEMELEN BİRİNİN E-POSTASINDA OLDUĞUDUR. BİR TERMİNAL BULUP GİRİN.",
["Pekâlâ. O tüpü bir havalandırma filtresine bağlayın, vanayı açıp şu aptalı gazlayın."] = "PEKÂLÂ. O TÜPÜ BİR HAVALANDIRMA FİLTRESİNE BAĞLAYIN, VANAYI AÇIP ŞU APTALI GAZLAYIN.",
["Pekâlâ. Panik odasının kapısı bir kod ve özel bir anahtarla açılıyor. Kodu ve anahtarı bulun yeter. Basit!"] = "PEKÂLÂ. PANİK ODASININ KAPISI BİR KOD VE ÖZEL BİR ANAHTARLA AÇILIYOR. KODU VE ANAHTARI BULUN YETER. BASİT!",
["Pekâlâ. Sikerler. Gereken bütün istihbaratı sunuculardan birine topladım. Biri alsın da tüyelim."] = "PEKÂLÂ. SİKERLER. GEREKEN BÜTÜN İSTİHBARATI SUNUCULARDAN BİRİNE TOPLADIM. BİRİ ALSIN DA TÜYELİM.",
["Pekâlâ. Sonunda o sıçanın, Hox'u satan ve hepimizi satmak isteyen ispiyoncunun peşine düşüyoruz. İşini bitirme zamanı. Şu an şehrin dışındaki bir FBI güvenli evine kapandığını biliyoruz. Bu güvenli evler genellikle aynı düzenle yapılır. Güzel büyük evler, bahçeler, 24 saat güvenlik ve büyük ihtimalle içeride bir panik odası. Vergilerinizin nereye gittiğini görüyor musunuz? Plan basit: içeri girin, muhbirimizi bulun ve işini bitirin. Orada aleyhimize kanıtlar da vardır diye düşünüyorum; onları da temizlemek iyi olur."] = "PEKÂLÂ. SONUNDA O SIÇANIN, HOX'U SATAN VE HEPİMİZİ SATMAK İSTEYEN İSPİYONCUNUN PEŞİNE DÜŞÜYORUZ. İŞİNİ BİTİRME ZAMANI. ŞU AN ŞEHRİN DIŞINDAKİ BİR FBI GÜVENLİ EVİNE KAPANDIĞINI BİLİYORUZ. BU GÜVENLİ EVLER GENELLİKLE AYNI DÜZENLE YAPILIR. GÜZEL BÜYÜK EVLER, BAHÇELER, 24 SAAT GÜVENLİK VE BÜYÜK İHTİMALLE İÇERİDE BİR PANİK ODASI. VERGİLERİNİZİN NEREYE GİTTİĞİNİ GÖRÜYOR MUSUNUZ? PLAN BASİT: İÇERİ GİRİN, MUHBİRİMİZİ BULUN VE İŞİNİ BİTİRİN. ORADA ALEYHİMİZE KANITLAR DA VARDIR DİYE DÜŞÜNÜYORUM; ONLARI DA TEMİZLEMEK İYİ OLUR.",
["Pekâlâ. Sonunda sıçanın peşine düşüyoruz. Hox'u yakan muhbir hepimizi yakmak istiyor. Onu indirme vakti. Şu an şehir dışındaki bir FBI güvenli evine sığındığını biliyoruz. Bu evler genelde aynı düzende yapılır. Güzel büyük evler, bahçe, 24 saat güvenlik ve büyük ihtimalle içeride bir panik odası. Vergileriniz nereye gidiyor, gördünüz mü? Plan basit: Girin, muhbirimizi bulun ve bitirin. Bahse girerim bize karşı kanıt da vardır, onları da temizlemek iyi olur."] = "PEKÂLÂ. SONUNDA SIÇANIN PEŞİNE DÜŞÜYORUZ. HOX'U YAKAN MUHBİR HEPİMİZİ YAKMAK İSTİYOR. ONU İNDİRME VAKTİ. ŞU AN ŞEHİR DIŞINDAKİ BİR FBI GÜVENLİ EVİNE SIĞINDIĞINI BİLİYORUZ. BU EVLER GENELDE AYNI DÜZENDE YAPILIR. GÜZEL BÜYÜK EVLER, BAHÇE, 24 SAAT GÜVENLİK VE BÜYÜK İHTİMALLE İÇERİDE BİR PANİK ODASI. VERGİLERİNİZ NEREYE GİDİYOR, GÖRDÜNÜZ MÜ? PLAN BASİT: GİRİN, MUHBİRİMİZİ BULUN VE BİTİRİN. BAHSE GİRERİM BİZE KARŞI KANIT DA VARDIR, ONLARI DA TEMİZLEMEK İYİ OLUR.",
["Pekâlâ. İlk hedef içeri girmek. Ön kapı tam ileride ama belki biraz kurnazlık edip başka girişler ararsınız."] = "PEKÂLÂ. İLK HEDEF İÇERİ GİRMEK. ÖN KAPI TAM İLERİDE AMA BELKİ BİRAZ KURNAZLIK EDİP BAŞKA GİRİŞLER ARARSINIZ.",
["Pekâlâ. Şimdi C4'ü oraya yapıştırın. Patlatarak çıkıyoruz."] = "PEKÂLÂ. ŞİMDİ C4'Ü ORAYA YAPIŞTIRIN. PATLATARAK ÇIKIYORUZ.",
["Pekâlâ. Şimdi Kasaya matkap yerleştirin, bahçe hortumunu da sığınağa indirin."] = "PEKÂLÂ. ŞİMDİ KASAYA MATKAP YERLEŞTİRİN, BAHÇE HORTUMUNU DA SIĞINAĞA İNDİRİN.",
["Pekâlâ. Şimdi o içeceği tatmasını bekleyelim. Her an tuvalete koşabilir. Peşinden gidin. Anahtar Kartını alın."] = "PEKÂLÂ. ŞİMDİ O İÇECEĞİ TATMASINI BEKLEYELİM. HER AN TUVALETE KOŞABİLİR. PEŞİNDEN GİDİN. ANAHTAR KARTINI ALIN.",
["Pekâlâ. Şimdi pişirmeye devam edebilir ya da helikoptere işaret verip bu işi bitirebilirsiniz."] = "PEKÂLÂ. ŞİMDİ PİŞİRMEYE DEVAM EDEBİLİR YA DA HELİKOPTERE İŞARET VERİP BU İŞİ BİTİREBİLİRSİNİZ.",
