["Sen ne yaptın?"] = "SEN NE YAPTIN?",
["Sen onlara ateş etmeye çalışırken polislerin hareketli bir duvarın arkasına saklanması hiç sportmence değil."] = "SEN ONLARA ATEŞ ETMEYE ÇALIŞIRKEN POLİSLERİN HAREKETLİ BİR DUVARIN ARKASINA SAKLANMASI HİÇ SPORTMENCE DEĞİL.",
["Sen ve dört kişilik ekibindeki herkes farklı bir \"Big Bank\" maskesi takarken herhangi bir soygunu tamamla."] = "SEN VE DÖRT KİŞİLİK EKİBİNDEKİ HERKES FARKLI BİR \"BİG BANK\" MASKESİ TAKARKEN HERHANGİ BİR SOYGUNU TAMAMLA.",
["Sen ve dört kişilik ekibindeki herkes farklı bir Christmas soundtrack veya topluluk \"Santa\" maskesi takarken bir soygunu tamamla."] = "SEN VE DÖRT KİŞİLİK EKİBİNDEKİ HERKES FARKLI BİR CHRİSTMAS SOUNDTRACK VEYA TOPLULUK \"SANTA\" MASKESİ TAKARKEN BİR SOYGUNU TAMAMLA.",
["Sen ve dört kişilik ekibindeki herkes farklı bir zorluk maskesi takarken bir soygunu tamamla."] = "SEN VE DÖRT KİŞİLİK EKİBİNDEKİ HERKES FARKLI BİR ZORLUK MASKESİ TAKARKEN BİR SOYGUNU TAMAMLA.",
["Sen! Kıpırda!"] = "SEN! KIPIRDA!",
["Senatör Borrico siyasette ve iş dünyasında ilerliyor. Bir ülkeyle kârlı bir silah anlaşması yaptığını öğrendim. Bu ülke ona saf altınla ödeme yapmış."] = "SENATÖR BORRİCO SİYASETTE VE İŞ DÜNYASINDA İLERLİYOR. BİR ÜLKEYLE KÂRLI BİR SİLAH ANLAŞMASI YAPTIĞINI ÖĞRENDİM. BU ÜLKE ONA SAF ALTINLA ÖDEME YAPMIŞ.",
["Senatör Borrico şu küçük altın karşılığı silah anlaşmasını tamamladığına göre artık tam kıvamında."] = "SENATÖR BORRİCO ŞU KÜÇÜK ALTIN KARŞILIĞI SİLAH ANLAŞMASINI TAMAMLADIĞINA GÖRE ARTIK TAM KIVAMINDA.",
["Senatör Borrico, biraz şaibeli bir ülkeyle ulusal çapta kazançlı bir silah anlaşması yaptı. Çatı katındaki dairesine girmenin bir yolunu bulun."] = "SENATÖR BORRİCO, BİRAZ ŞAİBELİ BİR ÜLKEYLE ULUSAL ÇAPTA KAZANÇLI BİR SİLAH ANLAŞMASI YAPTI. ÇATI KATINDAKİ DAİRESİNE GİRMENİN BİR YOLUNU BULUN.",
["Senatör sanat eseri toplamaya bayılıyor, özellikle de ana akım dışındaki sanata. Neyse ki Capitol Art Gallery bu hafta bir sergiye ev sahipliği yapıyor."] = "SENATÖR SANAT ESERİ TOPLAMAYA BAYILIYOR, ÖZELLİKLE DE ANA AKIM DIŞINDAKİ SANATA. NEYSE Kİ CAPİTOL ART GALLERY BU HAFTA BİR SERGİYE EV SAHİPLİĞİ YAPIYOR.",
["Senatör sanat eseri toplamaya bayılıyor; özellikle de ana akım dışındaki sanata. Neyse ki Capitol Art Gallery bu hafta bir sergiye ev sahipliği yapıyor. İşaretli tabloları senatörün dairesine ulaştırmamız gerekiyor. İçlerine kamera yerleştirilecek. İçeride gözümüzün olması işinizi kolaylaştıracak, bana güvenin."] = "SENATÖR SANAT ESERİ TOPLAMAYA BAYILIYOR; ÖZELLİKLE DE ANA AKIM DIŞINDAKİ SANATA. NEYSE Kİ CAPİTOL ART GALLERY BU HAFTA BİR SERGİYE EV SAHİPLİĞİ YAPIYOR. İŞARETLİ TABLOLARI SENATÖRÜN DAİRESİNE ULAŞTIRMAMIZ GEREKİYOR. İÇLERİNE KAMERA YERLEŞTİRİLECEK. İÇERİDE GÖZÜMÜZÜN OLMASI İŞİNİZİ KOLAYLAŞTIRACAK, BANA GÜVENİN.",
["Senatöre Tuzak"] = "SENATÖRE TUZAK",
["Senatörün adamları çok minnettar. Patron da tabloları asıyor. Herif onu silip süpüreceğimizden habersiz. Neyse. Bu arada parayı alırken iyi iş çıkardınız."] = "SENATÖRÜN ADAMLARI ÇOK MİNNETTAR. PATRON DA TABLOLARI ASIYOR. HERİF ONU SİLİP SÜPÜRECEĞİMİZDEN HABERSİZ. NEYSE. BU ARADA PARAYI ALIRKEN İYİ İŞ ÇIKARDINIZ.",
["Senatörün adamlarıyla bağlantıya geçip tabloları bizden almaya ikna edeceğim."] = "SENATÖRÜN ADAMLARIYLA BAĞLANTIYA GEÇİP TABLOLARI BİZDEN ALMAYA İKNA EDECEĞİM.",
["Senatörün adamlarıyla takası ayarlayıp işi ilerleteceğim."] = "SENATÖRÜN ADAMLARIYLA TAKASI AYARLAYIP İŞİ İLERLETECEĞİM.",
["Senatörün adamı az önce tabloları aldıklarını söyledi. Takastan çok memnunlar. Sizin iyi işiniz sayesinde şimdi tam istediğimiz yerdeler. Umarım o paradan siz de biraz almışsınızdır."] = "SENATÖRÜN ADAMI AZ ÖNCE TABLOLARI ALDIKLARINI SÖYLEDİ. TAKASTAN ÇOK MEMNUNLAR. SİZİN İYİ İŞİNİZ SAYESİNDE ŞİMDİ TAM İSTEDİĞİMİZ YERDELER. UMARIM O PARADAN SİZ DE BİRAZ ALMIŞSINIZDIR.",
