["Sessiz ilerliyorsunuz. Harika. Unutmayın, Anahtar Kartı lazım."] = "SESSİZ İLERLİYORSUNUZ. HARİKA. UNUTMAYIN, ANAHTAR KARTI LAZIM.",
["Sessiz kalın, ekip, ama ilerlemeyi de sürdürün. Garaja inin."] = "SESSİZ KALIN, EKİP, AMA İLERLEMEYİ DE SÜRDÜRÜN. GARAJA İNİN.",
["Sessiz kalın, ekip."] = "SESSİZ KALIN, EKİP.",
["Sessiz ol Dmitri. Annem hayaletlerin hep dinlediğini söylerdi."] = "SESSİZ OL DMİTRİ. ANNEM HAYALETLERİN HEP DİNLEDİĞİNİ SÖYLERDİ.",
["Sessiz olun. Görünmeyin."] = "SESSİZ OLUN. GÖRÜNMEYİN.",
["Sessiz tutabileceğinizi mi düşünüyorsunuz? Tebrikler, millet."] = "SESSİZ TUTABİLECEĞİNİZİ Mİ DÜŞÜNÜYORSUNUZ? TEBRİKLER, MİLLET.",
["Sessiz ve Açgözlü"] = "SESSİZ VE AÇGÖZLÜ",
["Sessiz yaklaşım yattı! Belaya hazır olun!"] = "SESSİZ YAKLAŞIM YATTI! BELAYA HAZIR OLUN!",
["Sessiz yaptığımızda zırhı buradan almıştık, hatırladınız mı?"] = "SESSİZ YAPTIĞIMIZDA ZIRHI BURADAN ALMIŞTIK, HATIRLADINIZ MI?",
["Sessiz yolu unutun artık..."] = "SESSİZ YOLU UNUTUN ARTIK...",
["Sessiz... Sessiz. Harika gidiyorsunuz."] = "SESSİZ... SESSİZ. HARİKA GİDİYORSUNUZ.",
["Sessizce gitmelerine izin verin."] = "SESSİZCE GİTMELERİNE İZİN VERİN.",
["Sessizce halletmeniz harikaydı. Sizden şüphelenmiyorlar, konteynerler açık. Girişin!"] = "SESSİZCE HALLETMENİZ HARİKAYDI. SİZDEN ŞÜPHELENMİYORLAR, KONTEYNERLER AÇIK. GİRİŞİN!",
["Sessizlik bitti. Ortalığı coşturma vakti!"] = "SESSİZLİK BİTTİ. ORTALIĞI COŞTURMA VAKTİ!",
["Sessizliğin Sesi"] = "SESSİZLİĞİN SESİ",
["Sevgili Fluffedup’ımız kayıp. 95 yaşında, ailemizin bir parçası. Fluffedup mutlu bir ufaklık; kesinlikle kendini birkaç kez blendere veya çatıdan aşağı atmaya çalışmadı. Onu sonsuza kadar tutmak, hiç bırakmamak istiyoruz. Bu yüzden bize, yaşayıp sevdiği ve kesinlikle nefret etmediği evimize dönmesi çok önemli!"] = "SEVGİLİ FLUFFEDUP’IMIZ KAYIP. 95 YAŞINDA, AİLEMİZİN BİR PARÇASI. FLUFFEDUP MUTLU BİR UFAKLIK; KESİNLİKLE KENDİNİ BİRKAÇ KEZ BLENDERE VEYA ÇATIDAN AŞAĞI ATMAYA ÇALIŞMADI. ONU SONSUZA KADAR TUTMAK, HİÇ BIRAKMAMAK İSTİYORUZ. BU YÜZDEN BİZE, YAŞAYIP SEVDİĞİ VE KESİNLİKLE NEFRET ETMEDİĞİ EVİMİZE DÖNMESİ ÇOK ÖNEMLİ!",
["Sevgili bebek İsa, beni koru..."] = "SEVGİLİ BEBEK İSA, BENİ KORU...",
["Sevgili dostlar! Beni görüyor musunuz? Evet, buradayım. Kesinlikle. Zahmet vermek istemem ama şu güzel parayı helikopterime bağlar mısınız?"] = "SEVGİLİ DOSTLAR! BENİ GÖRÜYOR MUSUNUZ? EVET, BURADAYIM. KESİNLİKLE. ZAHMET VERMEK İSTEMEM AMA ŞU GÜZEL PARAYI HELİKOPTERİME BAĞLAR MISINIZ?",
["Sevgili dostlar! Uçuşun keyfini çıkarıyorsunuz, değil mi? İndirme noktası olarak seçtiğim yere varmak üzeresiniz. O yüzden..."] = "SEVGİLİ DOSTLAR! UÇUŞUN KEYFİNİ ÇIKARIYORSUNUZ, DEĞİL Mİ? İNDİRME NOKTASI OLARAK SEÇTİĞİM YERE VARMAK ÜZERESİNİZ. O YÜZDEN...",
["Sevgili dostlar, Dentist ve o Murky pislikleri Bain’i ellerinde tutarken garip bir virüs bulaştırmış. Murky ana bilgisayarından biraz bilgi çektim; kod adını tanıyorum. Virüs, yıllar önce ABD hükümeti için biyolojik toksin geliştirdikleri sırada ellerine geçen bir şeyin iyileştirilmiş türü. Mevcut biyolojik savaş anlaşmalarındaki açıkları kullanıyorlardı. Eski bir biyotıp bağlantıma incelettim. Virüs bulaşıcı değil ama durum berbat. Tedavisi yok. Bain’in içeriden tükenmesine en fazla birkaç gün var. Bir keresinde Chains’e Bain’in bu gizli meseleye takıntısının ne zaman başladığını sormuştum. Yıllar önce, tecritteki bir hastanın kanıyla ilgili hastane işinde ödeme olarak verilen Cagliostro el yazmasını anlattı. Aynı sıralarda Murky’de büyük skandal ve örtbasla sonuçlanan bir olay hatırlıyorum. Murky’nin tıbbi test yaptığı... gönüllülerden... biri kaçmıştı ve kontrol altına alınması gerekiyordu. Tesadüf olamaz. Belki de Bain’in arayışı sonunda onun sonu olacak."] = "SEVGİLİ DOSTLAR, DENTİST VE O MURKY PİSLİKLERİ BAIN’İ ELLERİNDE TUTARKEN GARİP BİR VİRÜS BULAŞTIRMIŞ. MURKY ANA BİLGİSAYARINDAN BİRAZ BİLGİ ÇEKTİM; KOD ADINI TANIYORUM. VİRÜS, YILLAR ÖNCE ABD HÜKÜMETİ İÇİN BİYOLOJİK TOKSİN GELİŞTİRDİKLERİ SIRADA ELLERİNE GEÇEN BİR ŞEYİN İYİLEŞTİRİLMİŞ TÜRÜ. MEVCUT BİYOLOJİK SAVAŞ ANLAŞMALARINDAKİ AÇIKLARI KULLANIYORLARDI. ESKİ BİR BİYOTIP BAĞLANTIMA İNCELETTİM. VİRÜS BULAŞICI DEĞİL AMA DURUM BERBAT. TEDAVİSİ YOK. BAIN’İN İÇERİDEN TÜKENMESİNE EN FAZLA BİRKAÇ GÜN VAR. BİR KERESİNDE CHAINS’E BAIN’İN BU GİZLİ MESELEYE TAKINTISININ NE ZAMAN BAŞLADIĞINI SORMUŞTUM. YILLAR ÖNCE, TECRİTTEKİ BİR HASTANIN KANIYLA İLGİLİ HASTANE İŞİNDE ÖDEME OLARAK VERİLEN CAGLİOSTRO EL YAZMASINI ANLATTI. AYNI SIRALARDA MURKY’DE BÜYÜK SKANDAL VE ÖRTBASLA SONUÇLANAN BİR OLAY HATIRLIYORUM. MURKY’NİN TIBBİ TEST YAPTIĞI... GÖNÜLLÜLERDEN... BİRİ KAÇMIŞTI VE KONTROL ALTINA ALINMASI GEREKİYORDU. TESADÜF OLAMAZ. BELKİ DE BAIN’İN ARAYIŞI SONUNDA ONUN SONU OLACAK.",
["Sevgili dostlar, Elephant kutusuna benzer bir şeyi daha önce gördüğümü biliyordum. Çöldeki gizli bir Murkywater depolama ve araştırma tesisine yaptığım ziyareti hatırladım. Burası Murky’nin kalbi gibi; çılgın projelerle dolu. Gördüğüm azıcık şey bile o aptallarla daha ne kadar çalışmak istediğimi sorgulatmıştı. Bir arkadaş güvenlik görüntülerine sızmama yardım etti ve ellerinde neredeyse aynı iki kutu tuttuklarını öğrendik. Duke, Kataru’nun Baldwin’s Lament ile ilgili bir nedenle bunları toplamaya çalıştığından oldukça emin."] = "SEVGİLİ DOSTLAR, ELEPHANT KUTUSUNA BENZER BİR ŞEYİ DAHA ÖNCE GÖRDÜĞÜMÜ BİLİYORDUM. ÇÖLDEKİ GİZLİ BİR MURKYWATER DEPOLAMA VE ARAŞTIRMA TESİSİNE YAPTIĞIM ZİYARETİ HATIRLADIM. BURASI MURKY’NİN KALBİ GİBİ; ÇILGIN PROJELERLE DOLU. GÖRDÜĞÜM AZICIK ŞEY BİLE O APTALLARLA DAHA NE KADAR ÇALIŞMAK İSTEDİĞİMİ SORGULATMIŞTI. BİR ARKADAŞ GÜVENLİK GÖRÜNTÜLERİNE SIZMAMA YARDIM ETTİ VE ELLERİNDE NEREDEYSE AYNI İKİ KUTU TUTTUKLARINI ÖĞRENDİK. DUKE, KATARU’NUN BALDWİN’S LAMENT İLE İLGİLİ BİR NEDENLE BUNLARI TOPLAMAYA ÇALIŞTIĞINDAN OLDUKÇA EMİN.",
["Sevgili dostlar, New York'a dönüyoruz. Eski Brooklyn Bank'in temeline gömülmüş, Bain'in aradığı bir şey var. İçinde bulunduğumuz bu çıkmazdan kurtulmanın yolu olabilir. Oradayken işlerimizi sürdürebilmek için biraz da nakit toplamak iyi fikir olabilir. Bain'in bütün ekipmanlarını yenilemek ucuz olmayacak, bunu söyleyeyim. Yedek olarak çalıştırdığım şeyler de uzun süre dayanmaz, ha? Şu anda açık hedefiz."] = "SEVGİLİ DOSTLAR, NEW YORK'A DÖNÜYORUZ. ESKİ BROOKLYN BANK'İN TEMELİNE GÖMÜLMÜŞ, BAIN'İN ARADIĞI BİR ŞEY VAR. İÇİNDE BULUNDUĞUMUZ BU ÇIKMAZDAN KURTULMANIN YOLU OLABİLİR. ORADAYKEN İŞLERİMİZİ SÜRDÜREBİLMEK İÇİN BİRAZ DA NAKİT TOPLAMAK İYİ FİKİR OLABİLİR. BAIN'İN BÜTÜN EKİPMANLARINI YENİLEMEK UCUZ OLMAYACAK, BUNU SÖYLEYEYİM. YEDEK OLARAK ÇALIŞTIRDIĞIM ŞEYLER DE UZUN SÜRE DAYANMAZ, HA? ŞU ANDA AÇIK HEDEFİZ.",
["Sevgili dostlar, bana güvenmeseniz bile dinlemelisiniz, çünkü işler çok ağırlaşacak. Kısa süre önce Bain, peşinde olduğu Kutsal Kâse zımbırtısıyla ilgili yeni bilgi aldı. Ne olduğunu söylemedi... Ona inanmamakla ilgili bir şey dedi ama artık başkalarının da onu istediğini söyledi. İşleri düzeltmezsek Crimenet dâhil bütün operasyon boka gidecek. Elbette para için varım ama Bain'e borcum da var, ödemeye niyetliyim. Aldstone güvenli evin yeniden güvenli olduğunu söylüyor. Oraya dönün, haberleşiriz. İlgilenmem gereken şeyler var. Büyük hedefin peşine düşüyoruz... bir kayıp ruhu da geri getireceğiz."] = "SEVGİLİ DOSTLAR, BANA GÜVENMESENİZ BİLE DİNLEMELİSİNİZ, ÇÜNKÜ İŞLER ÇOK AĞIRLAŞACAK. KISA SÜRE ÖNCE BAIN, PEŞİNDE OLDUĞU KUTSAL KÂSE ZIMBIRTISIYLA İLGİLİ YENİ BİLGİ ALDI. NE OLDUĞUNU SÖYLEMEDİ... ONA İNANMAMAKLA İLGİLİ BİR ŞEY DEDİ AMA ARTIK BAŞKALARININ DA ONU İSTEDİĞİNİ SÖYLEDİ. İŞLERİ DÜZELTMEZSEK CRİMENET DÂHİL BÜTÜN OPERASYON BOKA GİDECEK. ELBETTE PARA İÇİN VARIM AMA BAIN'E BORCUM DA VAR, ÖDEMEYE NİYETLİYİM. ALDSTONE GÜVENLİ EVİN YENİDEN GÜVENLİ OLDUĞUNU SÖYLÜYOR. ORAYA DÖNÜN, HABERLEŞİRİZ. İLGİLENMEM GEREKEN ŞEYLER VAR. BÜYÜK HEDEFİN PEŞİNE DÜŞÜYORUZ... BİR KAYIP RUHU DA GERİ GETİRECEĞİZ.",
["Sevgili dostlar, biraz silah elden çıkarmak için yardıma ihtiyacım var. Alaska'da bir anlaşma ayarladım ama alışverişin güvenliğini sağlamak için bana eşlik etmelisiniz, tamam mı?"] = "SEVGİLİ DOSTLAR, BİRAZ SİLAH ELDEN ÇIKARMAK İÇİN YARDIMA İHTİYACIM VAR. ALASKA'DA BİR ANLAŞMA AYARLADIM AMA ALIŞVERİŞİN GÜVENLİĞİNİ SAĞLAMAK İÇİN BANA EŞLİK ETMELİSİNİZ, TAMAM MI?",
["Sevgili dostlar, birkaç silahı elden çıkarmak için yardımınıza ihtiyacım var. Alaska'da bir anlaşma ayarladım ama alışverişin güvenli olması için koruma lazım, tamam mı?"] = "SEVGİLİ DOSTLAR, BİRKAÇ SİLAHI ELDEN ÇIKARMAK İÇİN YARDIMINIZA İHTİYACIM VAR. ALASKA'DA BİR ANLAŞMA AYARLADIM AMA ALIŞVERİŞİN GÜVENLİ OLMASI İÇİN KORUMA LAZIM, TAMAM MI?",
["Sevgili dostlar, bu iş zor olacak. Kataru, Bain'in zımbırtısının peşine daha sıkı düştü; biz de oyuncaklarını ellerinden almalıyız, tamam mı? Vuracağımız depo, en önemli Murky tesisi ve orada çok tuhaf projeler üzerinde çalışıyorlar. Beni oraya yalnızca bir kez yaklaştırdılar, pek bir şey göremedim; neyle karşılaşacağımızı bilmiyoruz. Murky'de kalan bağlantılarıma borçlu oldukları bütün iyilikleri hatırlatıp bir giriş yolu ayarladım ama içeri körlemesine giriyoruz. Bunu yaptıktan sonra geri dönüş yok. Aslında Murkywater'a açıkça savaş ilan ediyoruz ama Bain için o şerefsizlere borcumuz var. Daha önce görmediğimiz düzeyde güvenlik olacak; içeri girince gevşemek yok."] = "SEVGİLİ DOSTLAR, BU İŞ ZOR OLACAK. KATARU, BAIN'İN ZIMBIRTISININ PEŞİNE DAHA SIKI DÜŞTÜ; BİZ DE OYUNCAKLARINI ELLERİNDEN ALMALIYIZ, TAMAM MI? VURACAĞIMIZ DEPO, EN ÖNEMLİ MURKY TESİSİ VE ORADA ÇOK TUHAF PROJELER ÜZERİNDE ÇALIŞIYORLAR. BENİ ORAYA YALNIZCA BİR KEZ YAKLAŞTIRDILAR, PEK BİR ŞEY GÖREMEDİM; NEYLE KARŞILAŞACAĞIMIZI BİLMİYORUZ. MURKY'DE KALAN BAĞLANTILARIMA BORÇLU OLDUKLARI BÜTÜN İYİLİKLERİ HATIRLATIP BİR GİRİŞ YOLU AYARLADIM AMA İÇERİ KÖRLEMESİNE GİRİYORUZ. BUNU YAPTIKTAN SONRA GERİ DÖNÜŞ YOK. ASLINDA MURKYWATER'A AÇIKÇA SAVAŞ İLAN EDİYORUZ AMA BAIN İÇİN O ŞEREFSİZLERE BORCUMUZ VAR. DAHA ÖNCE GÖRMEDİĞİMİZ DÜZEYDE GÜVENLİK OLACAK; İÇERİ GİRİNCE GEVŞEMEK YOK.",
["Sevgili dostlar, bu zorlu bir iş olacak. Kataru, Bain'in zımbırtısının peşine daha da hırsla düştü. Oyuncaklarını ellerinden almamız gerekiyor, ha? Vuracağımız depo, Murky'nin en önemli tesisi. Çok tuhaf projeler üzerinde çalışıyorlar. Beni oraya sadece bir kere yaklaştırdılar, pek bir şey görmedim. Yani neyle karşılaşacağımızı bilmiyoruz. Murky'de kalan bağlantılarıma son iyiliklerine kadar başvurup bir giriş yolu ayarladım ama körlemesine gireceğiz. Bunu yapınca dönüş olmayacak. Resmen Murky'ye açık savaş ilan ediyoruz ama Bain'in hesabını o piçlerden sormamız lazım. Daha önce görmediğimiz seviyede güvenlik olacak. İçeri girince işe yaramaz hâle gelmeyin, tamam mı?"] = "SEVGİLİ DOSTLAR, BU ZORLU BİR İŞ OLACAK. KATARU, BAIN'İN ZIMBIRTISININ PEŞİNE DAHA DA HIRSLA DÜŞTÜ. OYUNCAKLARINI ELLERİNDEN ALMAMIZ GEREKİYOR, HA? VURACAĞIMIZ DEPO, MURKY'NİN EN ÖNEMLİ TESİSİ. ÇOK TUHAF PROJELER ÜZERİNDE ÇALIŞIYORLAR. BENİ ORAYA SADECE BİR KERE YAKLAŞTIRDILAR, PEK BİR ŞEY GÖRMEDİM. YANİ NEYLE KARŞILAŞACAĞIMIZI BİLMİYORUZ. MURKY'DE KALAN BAĞLANTILARIMA SON İYİLİKLERİNE KADAR BAŞVURUP BİR GİRİŞ YOLU AYARLADIM AMA KÖRLEMESİNE GİRECEĞİZ. BUNU YAPINCA DÖNÜŞ OLMAYACAK. RESMEN MURKY'YE AÇIK SAVAŞ İLAN EDİYORUZ AMA BAIN'İN HESABINI O PİÇLERDEN SORMAMIZ LAZIM. DAHA ÖNCE GÖRMEDİĞİMİZ SEVİYEDE GÜVENLİK OLACAK. İÇERİ GİRİNCE İŞE YARAMAZ HÂLE GELMEYİN, TAMAM MI?",
["Sevgili dostlar, hızlı bir banka soygunu için New York'a gidiyoruz. "] = "SEVGİLİ DOSTLAR, HIZLI BİR BANKA SOYGUNU İÇİN NEW YORK'A GİDİYORUZ. ",
["Sevgili dostlar. Komiser Garrett, Murkywater'ın sahipleri olan şu Kataru denenlerin istediği bir nesneyi ele geçirmek için Elephant'ı uydurma suçlamalarla tutukladı. Nesneyi onlara vermek için bir anlaşma yapıyor. Karşılığında alacağı şeyin, işleri bittiğine göre Bain'in cesedi olduğunu tahmin ediyoruz. Kendilerini açığa çıkarmayı göze aldıklarına göre bu nesne onlar için çok önemli. İşin Bain'in Kutsal Kâse zımbırtısıyla ilgili olmasına da şaşırmam. Elephant'ın bu işteki rolünü, hâlâ bizim tarafımızda olup olmadığını henüz bilmiyoruz. İstesek de şu an ona yardım edemeyiz. Ama Garrett bu gece FBI karargâhında takasa hazırlanıyor olacak. Biz de planlarını bozacağız."] = "SEVGİLİ DOSTLAR. KOMİSER GARRETT, MURKYWATER'IN SAHİPLERİ OLAN ŞU KATARU DENENLERİN İSTEDİĞİ BİR NESNEYİ ELE GEÇİRMEK İÇİN ELEPHANT'I UYDURMA SUÇLAMALARLA TUTUKLADI. NESNEYİ ONLARA VERMEK İÇİN BİR ANLAŞMA YAPIYOR. KARŞILIĞINDA ALACAĞI ŞEYİN, İŞLERİ BİTTİĞİNE GÖRE BAIN'İN CESEDİ OLDUĞUNU TAHMİN EDİYORUZ. KENDİLERİNİ AÇIĞA ÇIKARMAYI GÖZE ALDIKLARINA GÖRE BU NESNE ONLAR İÇİN ÇOK ÖNEMLİ. İŞİN BAIN'İN KUTSAL KÂSE ZIMBIRTISIYLA İLGİLİ OLMASINA DA ŞAŞIRMAM. ELEPHANT'IN BU İŞTEKİ ROLÜNÜ, HÂLÂ BİZİM TARAFIMIZDA OLUP OLMADIĞINI HENÜZ BİLMİYORUZ. İSTESEK DE ŞU AN ONA YARDIM EDEMEYİZ. AMA GARRETT BU GECE FBI KARARGÂHINDA TAKASA HAZIRLANIYOR OLACAK. BİZ DE PLANLARINI BOZACAĞIZ.",
["Sevgili dostlarım. Hızlı bir teslim alma işi. Murkywater deposundan bana 'küçük bir şey' getirin."] = "SEVGİLİ DOSTLARIM. HIZLI BİR TESLİM ALMA İŞİ. MURKYWATER DEPOSUNDAN BANA 'KÜÇÜK BİR ŞEY' GETİRİN.",
["Sevgili konuklarım. En içten özürlerimi sunarım ama partimize son derece istenmeyen davetsiz misafirler gelmiş gibi görünüyor. Bu nedenle, elbette kendi güvenliğiniz için, çıkışlara yönelmenizi rica etmeliyim."] = "SEVGİLİ KONUKLARIM. EN İÇTEN ÖZÜRLERİMİ SUNARIM AMA PARTİMİZE SON DERECE İSTENMEYEN DAVETSİZ MİSAFİRLER GELMİŞ GİBİ GÖRÜNÜYOR. BU NEDENLE, ELBETTE KENDİ GÜVENLİĞİNİZ İÇİN, ÇIKIŞLARA YÖNELMENİZİ RİCA ETMELİYİM.",
["Sevgiyi Paylaş"] = "SEVGİYİ PAYLAŞ",
["Sevimli, sarkık kulaklı Frou Frou hiç de ürkek bir Afgan tazısı değil. Zeki ve kıvrak zekâlı bu dost, kurnazlığın yanı sıra akıl da isteyen soygunlarda yüzünü örtmek için ideal."] = "SEVİMLİ, SARKIK KULAKLI FROU FROU HİÇ DE ÜRKEK BİR AFGAN TAZISI DEĞİL. ZEKİ VE KIVRAK ZEKÂLI BU DOST, KURNAZLIĞIN YANI SIRA AKIL DA İSTEYEN SOYGUNLARDA YÜZÜNÜ ÖRTMEK İÇİN İDEAL.",
