["Siktir Git!"] = "SİKTİR GİT!",
["Siktir boktan iş. Polisler kasa dairesinin açılışını durdurdu. Yeniden çalıştırın ve yaklaşan her lanet herifi öldürün."] = "SİKTİR BOKTAN İŞ. POLİSLER KASA DAİRESİNİN AÇILIŞINI DURDURDU. YENİDEN ÇALIŞTIRIN VE YAKLAŞAN HER LANET HERİFİ ÖLDÜRÜN.",
["Siktir dostum, Brown'ın beyni üstüme sıçradı!"] = "SİKTİR DOSTUM, BROWN'IN BEYNİ ÜSTÜME SIÇRADI!",
