["Siktir dostum, kasanın şifresi neydi? O dosyaları yakmamız lazım!"] = "SİKTİR DOSTUM, KASANIN ŞİFRESİ NEYDİ? O DOSYALARI YAKMAMIZ LAZIM!",
["Siktir dostum, ne yapıyorduk biz? Ee... Ağaç! Ağacı bulun!"] = "SİKTİR DOSTUM, NE YAPIYORDUK BİZ? EE... AĞAÇ! AĞACI BULUN!",
["Siktir edin şu herifleri..."] = "SİKTİR EDİN ŞU HERİFLERİ...",
["Siktir et Yuri'yi. Peki... Bu sandıkları ne zaman açıyoruz?"] = "SİKTİR ET YURİ'Yİ. PEKİ... BU SANDIKLARI NE ZAMAN AÇIYORUZ?",
["Siktir et onu! Onları da siktir et! Bırak gelsinler diyorum. Benim için kolay paradan ibaretler."] = "SİKTİR ET ONU! ONLARI DA SİKTİR ET! BIRAK GELSİNLER DİYORUM. BENİM İÇİN KOLAY PARADAN İBARETLER.",
["Siktir et, buradasın ya?"] = "SİKTİR ET, BURADASIN YA?",
["Siktir et, doğaçlama yaparız."] = "SİKTİR ET, DOĞAÇLAMA YAPARIZ.",
["Siktir git!"] = "SİKTİR GİT!",
["Siktir git, votkada boğul geber. "] = "SİKTİR GİT, VOTKADA BOĞUL GEBER. ",
["Siktir millet! Roket atan bir hava araçları var!"] = "SİKTİR MİLLET! ROKET ATAN BİR HAVA ARAÇLARI VAR!",
["Siktir olup gidelim şu çöplükten."] = "SİKTİR OLUP GİDELİM ŞU ÇÖPLÜKTEN.",
["Siktir oğlu siktir!"] = "SİKTİR OĞLU SİKTİR!",
["Siktir!"] = "SİKTİR!",
["Siktir! Ah siktir!"] = "SİKTİR! AH SİKTİR!",
["Siktir! Aldım sanmıştım. Alamamışım. Yine dönüyorum."] = "SİKTİR! ALDIM SANMIŞTIM. ALAMAMIŞIM. YİNE DÖNÜYORUM.",
["Siktir! Arabanın alarmı çaldı! Gizlilik de buraya kadarmış."] = "SİKTİR! ARABANIN ALARMI ÇALDI! GİZLİLİK DE BURAYA KADARMIŞ.",
["Siktir! Artık herkes burada olduğunuzu biliyor."] = "SİKTİR! ARTIK HERKES BURADA OLDUĞUNUZU BİLİYOR.",
["Siktir! Aynasızlar burada!"] = "SİKTİR! AYNASIZLAR BURADA!",
["Siktir! Aynasızlar geldi!"] = "SİKTİR! AYNASIZLAR GELDİ!",
["Siktir! Bariyer dubaları kalkmış mı?! Düzeltin!"] = "SİKTİR! BARİYER DUBALARI KALKMIŞ MI?! DÜZELTİN!",
["Siktir! Bir güvenlik programını tetiklemiş olmalıyım. Bana bir erişim noktası bulun. Çabuk!"] = "SİKTİR! BİR GÜVENLİK PROGRAMINI TETİKLEMİŞ OLMALIYIM. BANA BİR ERİŞİM NOKTASI BULUN. ÇABUK!",
["Siktir! Bizi fark ettiler!"] = "SİKTİR! BİZİ FARK ETTİLER!",
["Siktir! Bu piçler uçaksavar savunması kurmuş! Bile, uçağı hemen geri çevir! Millet, paraşütleri kullanıp atlayın! Bir şeyler düşünürüz!"] = "SİKTİR! BU PİÇLER UÇAKSAVAR SAVUNMASI KURMUŞ! BILE, UÇAĞI HEMEN GERİ ÇEVİR! MİLLET, PARAŞÜTLERİ KULLANIP ATLAYIN! BİR ŞEYLER DÜŞÜNÜRÜZ!",
["Siktir! Bu piçler uçaksavar savunması kurmuş! Uçağı geri çevireceğim! Yoldaşlar, paraşütleri kullanıp atlayın! Bir yolunu buluruz!"] = "SİKTİR! BU PİÇLER UÇAKSAVAR SAVUNMASI KURMUŞ! UÇAĞI GERİ ÇEVİRECEĞİM! YOLDAŞLAR, PARAŞÜTLERİ KULLANIP ATLAYIN! BİR YOLUNU BULURUZ!",
["Siktir! Bugün ölmek istemiyorum!"] = "SİKTİR! BUGÜN ÖLMEK İSTEMİYORUM!",
["Siktir! Burada B planına geçmemiz gerekmez diye çok umut etmiştim!"] = "SİKTİR! BURADA B PLANINA GEÇMEMİZ GEREKMEZ DİYE ÇOK UMUT ETMİŞTİM!",
["Siktir! Dayanın dostlar. Dışarıdan bir güvenlik şirketinin adamları buraya geliyor. Etkinlik için olmalılar. İşinizin izlerini bulurlarsa alarmı çalarlar! Otoparkta karşılayıp indirin onları!"] = "SİKTİR! DAYANIN DOSTLAR. DIŞARIDAN BİR GÜVENLİK ŞİRKETİNİN ADAMLARI BURAYA GELİYOR. ETKİNLİK İÇİN OLMALILAR. İŞİNİZİN İZLERİNİ BULURLARSA ALARMI ÇALARLAR! OTOPARKTA KARŞILAYIP İNDİRİN ONLARI!",
["Siktir! Dikkatsiz bir piç helikoptere yakıt koymayı unutmuş. Yakıt hortumunu bağlar mısınız?"] = "SİKTİR! DİKKATSİZ BİR PİÇ HELİKOPTERE YAKIT KOYMAYI UNUTMUŞ. YAKIT HORTUMUNU BAĞLAR MISINIZ?",
["Siktir! Döner platform mekanizmasında kısa devre var gibi. Oraya çıkıp düzeltmelisiniz."] = "SİKTİR! DÖNER PLATFORM MEKANİZMASINDA KISA DEVRE VAR GİBİ. ORAYA ÇIKIP DÜZELTMELİSİNİZ.",
["Siktir! Döner tablada kısa devre var! Gidip tamir edin!"] = "SİKTİR! DÖNER TABLADA KISA DEVRE VAR! GİDİP TAMİR EDİN!",
["Siktir! Hay aksi! Kahretsin!"] = "SİKTİR! HAY AKSİ! KAHRETSİN!",
["Siktir! Hayır!"] = "SİKTİR! HAYIR!",
["Siktir! Her yerde domuz var. Ateş ede ede çıkmam gerekecek."] = "SİKTİR! HER YERDE DOMUZ VAR. ATEŞ EDE EDE ÇIKMAM GEREKECEK.",
["Siktir! Honduraslılar! Buradalar! Bizi öldürecekler!"] = "SİKTİR! HONDURASLILAR! BURADALAR! BİZİ ÖLDÜRECEKLER!",
["Siktir! Kara mayınları. Çimlerden ve kameraların görüşünden uzak durun."] = "SİKTİR! KARA MAYINLARI. ÇİMLERDEN VE KAMERALARIN GÖRÜŞÜNDEN UZAK DURUN.",
["Siktir! Lanet polisler erişim noktasını kapattı. Düzeltin!"] = "SİKTİR! LANET POLİSLER ERİŞİM NOKTASINI KAPATTI. DÜZELTİN!",
["Siktir! Motorcular peşinizde."] = "SİKTİR! MOTORCULAR PEŞİNİZDE.",
["Siktir! O numune yeterince saf değil. Başka bir parti deneyin."] = "SİKTİR! O NUMUNE YETERİNCE SAF DEĞİL. BAŞKA BİR PARTİ DENEYİN.",
["Siktir! Polis burada!"] = "SİKTİR! POLİS BURADA!",
["Siktir! Polis geldi!"] = "SİKTİR! POLİS GELDİ!",
["Siktir! Polisler her yere barikat kurmuş! Sanki biliyorlardı! Sizi biraz daha ileriden alacağım!"] = "SİKTİR! POLİSLER HER YERE BARİKAT KURMUŞ! SANKİ BİLİYORLARDI! SİZİ BİRAZ DAHA İLERİDEN ALACAĞIM!",
["Siktir! Pompa tıkandı. Basınç vanalarını çevirip akışı yeniden sağlayın."] = "SİKTİR! POMPA TIKANDI. BASINÇ VANALARINI ÇEVİRİP AKIŞI YENİDEN SAĞLAYIN.",
["Siktir! Siktir! Siktir! Siktir!"] = "SİKTİR! SİKTİR! SİKTİR! SİKTİR!",
["Siktir! Tamam, çelik halatı kullanmayı unutun. Polisler gelince adamımız kaçmak zorunda kaldı."] = "SİKTİR! TAMAM, ÇELİK HALATI KULLANMAYI UNUTUN. POLİSLER GELİNCE ADAMIMIZ KAÇMAK ZORUNDA KALDI.",
["Siktir! Tanrım dostum! Seni yukarıda görmedim."] = "SİKTİR! TANRIM DOSTUM! SENİ YUKARIDA GÖRMEDİM.",
["Siktir! Yanlış anahtar!"] = "SİKTİR! YANLIŞ ANAHTAR!",
["Siktir! Çıkışları kapattılar! Çıkamıyoruz!"] = "SİKTİR! ÇIKIŞLARI KAPATTILAR! ÇIKAMIYORUZ!",
["Siktir, Kasa'nın şifresi neydi? O dosyaları yakmalıyız!"] = "SİKTİR, KASA'NIN ŞİFRESİ NEYDİ? O DOSYALARI YAKMALIYIZ!",
["Siktir, alarm çaldı ama başardık. İyiyiz. O lanet Murky'ler neye uğradıklarını anlamayacak. Akan ise kuduracak. Bunu düşünmek hoşuma gidiyor. "] = "SİKTİR, ALARM ÇALDI AMA BAŞARDIK. İYİYİZ. O LANET MURKY'LER NEYE UĞRADIKLARINI ANLAMAYACAK. AKAN İSE KUDURACAK. BUNU DÜŞÜNMEK HOŞUMA GİDİYOR. ",
["Siktir, alarm çaldı! Bu soygun bitti. Ağır toplar gelmeden kaçmaya çalış. Çabuk!"] = "SİKTİR, ALARM ÇALDI! BU SOYGUN BİTTİ. AĞIR TOPLAR GELMEDEN KAÇMAYA ÇALIŞ. ÇABUK!",
["Siktir, alarm çaldı. Tamam ekip, gürültü koparma vakti."] = "SİKTİR, ALARM ÇALDI. TAMAM EKİP, GÜRÜLTÜ KOPARMA VAKTİ.",
["Siktir, beni nişana aldılar galiba. Acele edin!"] = "SİKTİR, BENİ NİŞANA ALDILAR GALİBA. ACELE EDİN!",
["Siktir, birimiz yakalanıp gözaltına alındı! Bain, yeni araç lazım! Hemen!"] = "SİKTİR, BİRİMİZ YAKALANIP GÖZALTINA ALINDI! BAIN, YENİ ARAÇ LAZIM! HEMEN!",
["Siktir, birimiz yakalanıp gözaltına alındı! Yeni kaçış planı gerek!"] = "SİKTİR, BİRİMİZ YAKALANIP GÖZALTINA ALINDI! YENİ KAÇIŞ PLANI GEREK!",
["Siktir, birisi polisleri aramış olmalı."] = "SİKTİR, BİRİSİ POLİSLERİ ARAMIŞ OLMALI.",
["Siktir, bize nasıl ulaştılar?"] = "SİKTİR, BİZE NASIL ULAŞTILAR?",
["Siktir, bizi mi bekliyorlardı?"] = "SİKTİR, BİZİ Mİ BEKLİYORLARDI?",
["Siktir, bu ileri bilim işi. Kafaları çalıştırın. Renk kodu, kimyasal falan, her şey ipucu olabilir."] = "SİKTİR, BU İLERİ BİLİM İŞİ. KAFALARI ÇALIŞTIRIN. RENK KODU, KİMYASAL FALAN, HER ŞEY İPUCU OLABİLİR.",
["Siktir, bu nasıl hareket! İçeri girin! Silahları konuşturarak dalın, içeri girmeliyiz!"] = "SİKTİR, BU NASIL HAREKET! İÇERİ GİRİN! SİLAHLARI KONUŞTURARAK DALIN, İÇERİ GİRMELİYİZ!",
["Siktir, bu zor olacak... Evet, kendiniz yapamazsınız. Beni garaja götürün, bu güzelliğe özel parçalar toplamak için bir motoru sökeyim."] = "SİKTİR, BU ZOR OLACAK... EVET, KENDİNİZ YAPAMAZSINIZ. BENİ GARAJA GÖTÜRÜN, BU GÜZELLİĞE ÖZEL PARÇALAR TOPLAMAK İÇİN BİR MOTORU SÖKEYİM.",
["Siktir, burada bir muhafız daha var"] = "SİKTİR, BURADA BİR MUHAFIZ DAHA VAR",
["Siktir, burada bir muhafız var."] = "SİKTİR, BURADA BİR MUHAFIZ VAR.",
["Siktir, daha fazla polis!"] = "SİKTİR, DAHA FAZLA POLİS!",
["Siktir, federaller yakında burada olacak. Sunucu odasının kapısına hemen girişin."] = "SİKTİR, FEDERALLER YAKINDA BURADA OLACAK. SUNUCU ODASININ KAPISINA HEMEN GİRİŞİN.",
["Siktir, geliyorlar!"] = "SİKTİR, GELİYORLAR!",
["Siktir, gidiyorlar! Kusura bakmayın millet, B planı gibi görünüyor. Buradan çıkıp başka yerde halledelim."] = "SİKTİR, GİDİYORLAR! KUSURA BAKMAYIN MİLLET, B PLANI GİBİ GÖRÜNÜYOR. BURADAN ÇIKIP BAŞKA YERDE HALLEDELİM.",
["Siktir, görüşme dosyalarına erişemiyorum. Bizzat FBI Direktöründen onay gerekiyor. Ofisini bulun. Yerine geçebiliyor musunuz bakın."] = "SİKTİR, GÖRÜŞME DOSYALARINA ERİŞEMİYORUM. BİZZAT FBI DİREKTÖRÜNDEN ONAY GEREKİYOR. OFİSİNİ BULUN. YERİNE GEÇEBİLİYOR MUSUNUZ BAKIN.",
["Siktir, hak etmiştim galiba!"] = "SİKTİR, HAK ETMİŞTİM GALİBA!",
["Siktir, her yer polis. Ateş ederek çıkacağım galiba."] = "SİKTİR, HER YER POLİS. ATEŞ EDEREK ÇIKACAĞIM GALİBA.",
["Siktir, kötü polisler geliyor; hem de çok kötü polisler. Başınızı eğin!"] = "SİKTİR, KÖTÜ POLİSLER GELİYOR; HEM DE ÇOK KÖTÜ POLİSLER. BAŞINIZI EĞİN!",
["Siktir, lanet olsun!"] = "SİKTİR, LANET OLSUN!",
["Siktir, ne patlamaydı!"] = "SİKTİR, NE PATLAMAYDI!",
["Siktir, paralı askerler EMP'nin dolmasını durdurdu! Yükü boşalmaya başlıyor!"] = "SİKTİR, PARALI ASKERLER EMP'NİN DOLMASINI DURDURDU! YÜKÜ BOŞALMAYA BAŞLIYOR!",
["Siktir, polis burada!"] = "SİKTİR, POLİS BURADA!",
["Siktir, siktir!"] = "SİKTİR, SİKTİR!",
["Siktir, siktir, siktir! Daha fazlası var!"] = "SİKTİR, SİKTİR, SİKTİR! DAHA FAZLASI VAR!",
["Siktir, yakındaki evlerde hazır bekleyen FBI ekipleri var. Yola çıktılar."] = "SİKTİR, YAKINDAKİ EVLERDE HAZIR BEKLEYEN FBI EKİPLERİ VAR. YOLA ÇIKTILAR.",
["Siktir, yanlış anahtar!"] = "SİKTİR, YANLIŞ ANAHTAR!",
["Siktir, zaman kilidi durakladı. Onu çıldırtan ECM karıştırıcınız olmalı! O karıştırıcıları kaldırsanız iyi olur."] = "SİKTİR, ZAMAN KİLİDİ DURAKLADI. ONU ÇILDIRTAN ECM KARIŞTIRICINIZ OLMALI! O KARIŞTIRICILARI KALDIRSANIZ İYİ OLUR.",
["Siktir, çok ayrıntılıymış. Bizi kim ispiyonluyorsa... yakınımızdan biri."] = "SİKTİR, ÇOK AYRINTILIYMIŞ. BİZİ KİM İSPİYONLUYORSA... YAKINIMIZDAN BİRİ.",
["Siktir, çok hasar aldım. Gitmem gerek, geri geleceğim!"] = "SİKTİR, ÇOK HASAR ALDIM. GİTMEM GEREK, GERİ GELECEĞİM!",
["Siktir, ıskaladım. Dönüp bir daha deneyeceğim. Bir dakika kadar daha dayanın!"] = "SİKTİR, ISKALADIM. DÖNÜP BİR DAHA DENEYECEĞİM. BİR DAKİKA KADAR DAHA DAYANIN!",
["Siktir. Başka bir kamera."] = "SİKTİR. BAŞKA BİR KAMERA.",
["Siktir. Bu çocuk oyuncağı olacaktı."] = "SİKTİR. BU ÇOCUK OYUNCAĞI OLACAKTI.",
["Siktir. Buranın çevrildiğini görüyorum. Savaşarak çıkamazsınız. Konteynere girin!"] = "SİKTİR. BURANIN ÇEVRİLDİĞİNİ GÖRÜYORUM. SAVAŞARAK ÇIKAMAZSINIZ. KONTEYNERE GİRİN!",
["Siktir. Hapishane leş kokuyor... En azından üst ranza benim-"] = "SİKTİR. HAPİSHANE LEŞ KOKUYOR... EN AZINDAN ÜST RANZA BENİM-",
["Siktir. Matkap sıkıştı. Resmen dejavu."] = "SİKTİR. MATKAP SIKIŞTI. RESMEN DEJAVU.",
["Siktir. Sadece... Siktir."] = "SİKTİR. SADECE... SİKTİR.",
["Siktir. Sunucularda olmayan birkaç dosya lazım. Arşivlerde tutulan tanık ifadeleri. Oraya gidin."] = "SİKTİR. SUNUCULARDA OLMAYAN BİRKAÇ DOSYA LAZIM. ARŞİVLERDE TUTULAN TANIK İFADELERİ. ORAYA GİDİN.",
["Siktirin gidiiin! Çıkıp hepinizi yok edeceğim!"] = "SİKTİRİN GİDİİİN! ÇIKIP HEPİNİZİ YOK EDECEĞİM!",
["Siktirin gidin oradan!"] = "SİKTİRİN GİDİN ORADAN!",
["Siktirin gidin, anlaşma iptal!!!"] = "SİKTİRİN GİDİN, ANLAŞMA İPTAL!!!",
["Siktirin gidin, hepiniz!"] = "SİKTİRİN GİDİN, HEPİNİZ!",
["Siktirip gidin buradan!"] = "SİKTİRİP GİDİN BURADAN!",
["Siktiğimin Fransız'ıyla konuşur gibi. Dinleyin. Lokantadaki servis merdivenini kullanmak istiyorsanız Anahtar Kartı lazım. Mon dieu!"] = "SİKTİĞİMİN FRANSIZ'IYLA KONUŞUR GİBİ. DİNLEYİN. LOKANTADAKİ SERVİS MERDİVENİNİ KULLANMAK İSTİYORSANIZ ANAHTAR KARTI LAZIM. MON DİEU!",
["Siktiğimin Hector'ı. İnsan niye federallere böyle götünü açar ki? Ah siktir et. Harika iş çocuklar."] = "SİKTİĞİMİN HECTOR'I. İNSAN NİYE FEDERALLERE BÖYLE GÖTÜNÜ AÇAR Kİ? AH SİKTİR ET. HARİKA İŞ ÇOCUKLAR.",
["Siktiğimin Spider-Man'i gibi duvara tırmanmanız gerekiyorsa umurumda değil. Üçüncü palet için her yere bakın."] = "SİKTİĞİMİN SPİDER-MAN'İ GİBİ DUVARA TIRMANMANIZ GEREKİYORSA UMURUMDA DEĞİL. ÜÇÜNCÜ PALET İÇİN HER YERE BAKIN.",
["Siktiğimin arabasını değiştirmeliydik!"] = "SİKTİĞİMİN ARABASINI DEĞİŞTİRMELİYDİK!",
["Siktiğimin ayakkabı kutusunu bulmak ne kadar zor olabilir?"] = "SİKTİĞİMİN AYAKKABI KUTUSUNU BULMAK NE KADAR ZOR OLABİLİR?",
["Siktiğimin bok kuşları. Yukarıda şu eşyanızı sabitleyin."] = "SİKTİĞİMİN BOK KUŞLARI. YUKARIDA ŞU EŞYANIZI SABİTLEYİN.",
["Siktiğimin boktan arabası! Burada yardıma ihtiyacım var, millet!"] = "SİKTİĞİMİN BOKTAN ARABASI! BURADA YARDIMA İHTİYACIM VAR, MİLLET!",
["Siktiğimin güvenli evini boş verin. Bir planım var. Siz de bana yardım etmek istiyorsunuz, değil mi çocuklar?"] = "SİKTİĞİMİN GÜVENLİ EVİNİ BOŞ VERİN. BİR PLANIM VAR. SİZ DE BANA YARDIM ETMEK İSTİYORSUNUZ, DEĞİL Mİ ÇOCUKLAR?",
["Siktiğimin helikopterini alt geçitte atlattık sanıyordum!"] = "SİKTİĞİMİN HELİKOPTERİNİ ALT GEÇİTTE ATLATTIK SANIYORDUM!",
["Siktiğimin herifleri işinizi bozdu! Baştan başlamanız gerekecek."] = "SİKTİĞİMİN HERİFLERİ İŞİNİZİ BOZDU! BAŞTAN BAŞLAMANIZ GEREKECEK.",
["Siktiğimin kayınbiraderinden daha iyi, değil mi? Adı neydi... Hoojin ya da öyle bir bok? Ne istiyorsun lan?"] = "SİKTİĞİMİN KAYINBİRADERİNDEN DAHA İYİ, DEĞİL Mİ? ADI NEYDİ... HOOJİN YA DA ÖYLE BİR BOK? NE İSTİYORSUN LAN?",
["Siktiğimin orospu çocuğu!"] = "SİKTİĞİMİN OROSPU ÇOCUĞU!",
["Siktiğimin otuzbircilerinin akıncıları."] = "SİKTİĞİMİN OTUZBİRCİLERİNİN AKINCILARI.",
["Siktiğimin takım elbiselileri..."] = "SİKTİĞİMİN TAKIM ELBİSELİLERİ...",
["Siktiğimin telefonları sikilmiş. Ah, dostlarım!"] = "SİKTİĞİMİN TELEFONLARI SİKİLMİŞ. AH, DOSTLARIM!",
["Siktiğimin yetmişleri gibiydi dostum. Para, kokain, fahişeler... Hepsi bizdeydi."] = "SİKTİĞİMİN YETMİŞLERİ GİBİYDİ DOSTUM. PARA, KOKAİN, FAHİŞELER... HEPSİ BİZDEYDİ.",
["Siktiğimin çıkartması gibi yapıştılar bize!"] = "SİKTİĞİMİN ÇIKARTMASI GİBİ YAPIŞTILAR BİZE!",
