["Silahlar alınmaya hazır. Uçağa sinyal vermek için balonu sal, ardından kafes alınana kadar savun."] = "SİLAHLAR ALINMAYA HAZIR. UÇAĞA SİNYAL VERMEK İÇİN BALONU SAL, ARDINDAN KAFES ALINANA KADAR SAVUN.",
["Silahlar alınıyor"] = "SİLAHLAR ALINIYOR",
