["Sizce bunun anlamı ne? Şu Wang denen herife uyuyor gibi: Ching-wah TSAO duh liou mahnge."] = "SİZCE BUNUN ANLAMI NE? ŞU WANG DENEN HERİFE UYUYOR GİBİ: CHİNG-WAH TSAO DUH LİOU MAHNGE.",
["Size acı çektireceğim aptallar!"] = "SİZE ACI ÇEKTİRECEĞİM APTALLAR!",
["Size asla söylemeyeceğim!"] = "SİZE ASLA SÖYLEMEYECEĞİM!",
["Size bir adamım geliyor. Boris?"] = "SİZE BİR ADAMIM GELİYOR. BORİS?",
