["Size bir dizüstü buldum millet."] = "SİZE BİR DİZÜSTÜ BULDUM MİLLET.",
["Size bir fal kurabiyesi bilgeliği: Başarı önceden yapılan hazırlığa bağlıdır. Böyle bir hazırlık yoksa başarısızlık kesindir."] = "SİZE BİR FAL KURABİYESİ BİLGELİĞİ: BAŞARI ÖNCEDEN YAPILAN HAZIRLIĞA BAĞLIDIR. BÖYLE BİR HAZIRLIK YOKSA BAŞARISIZLIK KESİNDİR.",
["Size bir hastane işi var. Ameliyathane kıyafetlerinizi giyin!"] = "SİZE BİR HASTANE İŞİ VAR. AMELİYATHANE KIYAFETLERİNİZİ GİYİN!",
