["Size güzel bir sürpriz var. Cloaker'larımız artık kelepçe taşıyor!"] = "SİZE GÜZEL BİR SÜRPRİZ VAR. CLOAKER'LARIMIZ ARTIK KELEPÇE TAŞIYOR!",
["Size hazır olun demiştim!"] = "SİZE HAZIR OLUN DEMİŞTİM!",
