["Size kaçış minibüsü buldum, ana girişin hemen dışında!"] = "SİZE KAÇIŞ MİNİBÜSÜ BULDUM, ANA GİRİŞİN HEMEN DIŞINDA!",
["Size keskin nişancılarla saldıracaklar!"] = "SİZE KESKİN NİŞANCILARLA SALDIRACAKLAR!",
["Size malzeme getiremem. Şüphelenip beni vururlar. Ben bir şey düşünürken etrafa bakın."] = "SİZE MALZEME GETİREMEM. ŞÜPHELENİP BENİ VURURLAR. BEN BİR ŞEY DÜŞÜNÜRKEN ETRAFA BAKIN.",
["Size memnuniyetle yardımcı olurum. Bir dakika lütfen."] = "SİZE MEMNUNİYETLE YARDIMCI OLURUM. BİR DAKİKA LÜTFEN.",
