["Size oyuncaklar veriyorum, siz hâlâ kutuda kalmak istiyorsunuz. Harekete geçin!"] = "SİZE OYUNCAKLAR VERİYORUM, SİZ HÂLÂ KUTUDA KALMAK İSTİYORSUNUZ. HAREKETE GEÇİN!",
["Size tek sözüm var: Vuhuuuuuuuuuuuuuuuuu!"] = "SİZE TEK SÖZÜM VAR: VUHUUUUUUUUUUUUUUUUU!",
["Size yardım bulana kadar direnmeniz gerek."] = "SİZE YARDIM BULANA KADAR DİRENMENİZ GEREK.",
["Size yardım edebilecek bir şoförüm var. Eddie, hemen oraya git! Payday Gang'i alman gerek!"] = "SİZE YARDIM EDEBİLECEK BİR ŞOFÖRÜM VAR. EDDİE, HEMEN ORAYA GİT! PAYDAY GANG'İ ALMAN GEREK!",
["Size yardım etmek için güvenilir bir ortağın orada olmasını sağlayacağım."] = "SİZE YARDIM ETMEK İÇİN GÜVENİLİR BİR ORTAĞIN ORADA OLMASINI SAĞLAYACAĞIM.",
["Size yardım etmekten memnun olurum. Bir saniye lütfen."] = "SİZE YARDIM ETMEKTEN MEMNUN OLURUM. BİR SANİYE LÜTFEN.",
["Size yardımcı olmak bana büyük mutluluk verir."] = "SİZE YARDIMCI OLMAK BANA BÜYÜK MUTLULUK VERİR.",
["Size yeni bir matkap yolladım. Eski bir modeli esas alıyor ama bu sıkışmayacak."] = "SİZE YENİ BİR MATKAP YOLLADIM. ESKİ BİR MODELİ ESAS ALIYOR AMA BU SIKIŞMAYACAK.",
["Size yolladığım şey o kasa dairesinin başına fena bela olacak!"] = "SİZE YOLLADIĞIM ŞEY O KASA DAİRESİNİN BAŞINA FENA BELA OLACAK!",
["Sizi CEO'muza bağlıyorum. Lütfen bekleyin."] = "SİZİ CEO'MUZA BAĞLIYORUM. LÜTFEN BEKLEYİN.",
["Sizi Commissar'ın mekânına sokmak için sandık kullanıyoruz. Truva Atı usulü. Dairesi şehrin boktan bir yerindeki pis bir çöplük. Güvenlik pek iyi değil ama eminim o ve adamları kenarda bir koz tutuyordur. Hedef basit: Commissar'ı bulun ve öldürün. Ortalık gürültülü olacak, ona göre kuşanın."] = "SİZİ COMMİSSAR'IN MEKÂNINA SOKMAK İÇİN SANDIK KULLANIYORUZ. TRUVA ATI USULÜ. DAİRESİ ŞEHRİN BOKTAN BİR YERİNDEKİ PİS BİR ÇÖPLÜK. GÜVENLİK PEK İYİ DEĞİL AMA EMİNİM O VE ADAMLARI KENARDA BİR KOZ TUTUYORDUR. HEDEF BASİT: COMMİSSAR'I BULUN VE ÖLDÜRÜN. ORTALIK GÜRÜLTÜLÜ OLACAK, ONA GÖRE KUŞANIN.",
["Sizi alacak adam arkanızdaki sokakta."] = "SİZİ ALACAK ADAM ARKANIZDAKİ SOKAKTA.",
["Sizi alacak adam yakınlarda, sarı vinci arayın."] = "SİZİ ALACAK ADAM YAKINLARDA, SARI VİNCİ ARAYIN.",
["Sizi alacak araç yolda. Burada hataya pek yer yok. Çatıya çıkın."] = "SİZİ ALACAK ARAÇ YOLDA. BURADA HATAYA PEK YER YOK. ÇATIYA ÇIKIN.",
["Sizi alacak helikopter gelene kadar dayan."] = "SİZİ ALACAK HELİKOPTER GELENE KADAR DAYAN.",
["Sizi alacak uçak yolda ama ağaçlar yolu kapatırken inemez. Testere bulun, ağaçları temizleyin, iniş yerini işaret fişekleriyle belirleyin. Merak etmeyin, CIA bunu yıllardır yapıyor."] = "SİZİ ALACAK UÇAK YOLDA AMA AĞAÇLAR YOLU KAPATIRKEN İNEMEZ. TESTERE BULUN, AĞAÇLARI TEMİZLEYİN, İNİŞ YERİNİ İŞARET FİŞEKLERİYLE BELİRLEYİN. MERAK ETMEYİN, CIA BUNU YILLARDIR YAPIYOR.",
["Sizi alacak şoför geldi. Ganimeti kamyonun kasasına yükleyin!"] = "SİZİ ALACAK ŞOFÖR GELDİ. GANİMETİ KAMYONUN KASASINA YÜKLEYİN!",
["Sizi almak için bekleyen bir tekne var."] = "SİZİ ALMAK İÇİN BEKLEYEN BİR TEKNE VAR.",
["Sizi almak için daha yüksek bir noktaya geçmeliyim. Aşağısı fazla dar."] = "SİZİ ALMAK İÇİN DAHA YÜKSEK BİR NOKTAYA GEÇMELİYİM. AŞAĞISI FAZLA DAR.",
["Sizi almama iki dakika var. Dayanın millet."] = "SİZİ ALMAMA İKİ DAKİKA VAR. DAYANIN MİLLET.",
["Sizi alması için helikopter çağırıyorum!"] = "SİZİ ALMASI İÇİN HELİKOPTER ÇAĞIRIYORUM!",
["Sizi almaya bir helikopter geliyor. Pilotla tanıştığınızı sanıyorum."] = "SİZİ ALMAYA BİR HELİKOPTER GELİYOR. PİLOTLA TANIŞTIĞINIZI SANIYORUM.",
["Sizi almaya helikopter ayarladım. Tanıdık birini buldum, uçuş millerinizi kullanabilirsiniz."] = "SİZİ ALMAYA HELİKOPTER AYARLADIM. TANIDIK BİRİNİ BULDUM, UÇUŞ MİLLERİNİZİ KULLANABİLİRSİNİZ.",
["Sizi almaya helikopter geliyor ama biraz sürecek."] = "SİZİ ALMAYA HELİKOPTER GELİYOR AMA BİRAZ SÜRECEK.",
["Sizi almaya küçük bir uçak yolluyorum. Ama o ağaçlar yüzünden pilot inemez. Bir testere bulup birkaçını kesin, sonra da pisti onun için işaretleyin."] = "SİZİ ALMAYA KÜÇÜK BİR UÇAK YOLLUYORUM. AMA O AĞAÇLAR YÜZÜNDEN PİLOT İNEMEZ. BİR TESTERE BULUP BİRKAÇINI KESİN, SONRA DA PİSTİ ONUN İÇİN İŞARETLEYİN.",
["Sizi amcıklar, ben tatildeyken aklınızı mı yitirdiniz? Ne yaptığımı biliyorum."] = "SİZİ AMCIKLAR, BEN TATİLDEYKEN AKLINIZI MI YİTİRDİNİZ? NE YAPTIĞIMI BİLİYORUM.",
["Sizi aptallar! Garrett bize canlı lazımdı!"] = "SİZİ APTALLAR! GARRETT BİZE CANLI LAZIMDI!",
["Sizi aşarlarsa ne olacağını biliyorsunuz!"] = "SİZİ AŞARLARSA NE OLACAĞINI BİLİYORSUNUZ!",
["Sizi bekliyor olacak."] = "SİZİ BEKLİYOR OLACAK.",
["Sizi bekliyorduk piçler!"] = "SİZİ BEKLİYORDUK PİÇLER!",
["Sizi bekliyordum. Ekipmanınız kabin tuvaletlerinden birinde bekliyor ama ufak bir sorun var. Kasa Dairesinin güvenliği değişti. Kod hâlâ Li Deng'de ama açmak için Xun Kang'in el izi de gerekecek. Biraz kalıp mumu bulup ekipmanınızın yanına koyabildim. Bol şans."] = "SİZİ BEKLİYORDUM. EKİPMANINIZ KABİN TUVALETLERİNDEN BİRİNDE BEKLİYOR AMA UFAK BİR SORUN VAR. KASA DAİRESİNİN GÜVENLİĞİ DEĞİŞTİ. KOD HÂLÂ Lİ DENG'DE AMA AÇMAK İÇİN XUN KANG'İN EL İZİ DE GEREKECEK. BİRAZ KALIP MUMU BULUP EKİPMANINIZIN YANINA KOYABİLDİM. BOL ŞANS.",
["Sizi bekliyorum. Tekneyi bana doğru sürmeye devam edin."] = "SİZİ BEKLİYORUM. TEKNEYİ BANA DOĞRU SÜRMEYE DEVAM EDİN.",
["Sizi bilmem ama ben susuzluktan ölüyorum. Biriniz tatlılık edip otomattan bana kola getirir mi?"] = "SİZİ BİLMEM AMA BEN SUSUZLUKTAN ÖLÜYORUM. BİRİNİZ TATLILIK EDİP OTOMATTAN BANA KOLA GETİRİR Mİ?",
["Sizi bir sürü ekipman bekliyor dostlar."] = "SİZİ BİR SÜRÜ EKİPMAN BEKLİYOR DOSTLAR.",
["Sizi bulmadan defolun oradan!"] = "SİZİ BULMADAN DEFOLUN ORADAN!",
["Sizi bundan nasıl çıkaracak?"] = "SİZİ BUNDAN NASIL ÇIKARACAK?",
["Sizi burada indiriyorum. Çıkmaya hazır olun!"] = "SİZİ BURADA İNDİRİYORUM. ÇIKMAYA HAZIR OLUN!",
