["Sizi dedektiflik dehaları! Kamyona getirin, buradaki işimiz bitsin."] = "SİZİ DEDEKTİFLİK DEHALARI! KAMYONA GETİRİN, BURADAKİ İŞİMİZ BİTSİN.",
["Sizi durdurmaya çalışan olursa, Mendoza, polis, her kimse, uygun şekilde halledin. Toplumun onaylayacağı bir yöntem olması gerekmiyor."] = "SİZİ DURDURMAYA ÇALIŞAN OLURSA, MENDOZA, POLİS, HER KİMSE, UYGUN ŞEKİLDE HALLEDİN. TOPLUMUN ONAYLAYACAĞI BİR YÖNTEM OLMASI GEREKMİYOR.",
["Sizi endişelendirmek istemem. Ama batırırsanız... Kötü olur."] = "SİZİ ENDİŞELENDİRMEK İSTEMEM. AMA BATIRIRSANIZ... KÖTÜ OLUR.",
["Sizi fark etmemeleri için kameraların altından gizlice geçmeyi unutmayın."] = "SİZİ FARK ETMEMELERİ İÇİN KAMERALARIN ALTINDAN GİZLİCE GEÇMEYİ UNUTMAYIN.",
["Sizi fark ettiler!"] = "SİZİ FARK ETTİLER!",
["Sizi fark ettiler! Bir şey yapın, çabuk!"] = "SİZİ FARK ETTİLER! BİR ŞEY YAPIN, ÇABUK!",
["Sizi göle yollayacağız!"] = "SİZİ GÖLE YOLLAYACAĞIZ!",
["Sizi gömeceğim!"] = "SİZİ GÖMECEĞİM!",
["Sizi gördü! Halledin!"] = "SİZİ GÖRDÜ! HALLEDİN!",
["Sizi gördüler! Herifler yakında yola çıkar!"] = "SİZİ GÖRDÜLER! HERİFLER YAKINDA YOLA ÇIKAR!",
["Sizi gördüler! Kamyonlar gidiyor. Tamam, B planı lazım. Bir düşüneyim."] = "SİZİ GÖRDÜLER! KAMYONLAR GİDİYOR. TAMAM, B PLANI LAZIM. BİR DÜŞÜNEYİM.",
["Sizi gördüler. Artık zaman çok önemli."] = "SİZİ GÖRDÜLER. ARTIK ZAMAN ÇOK ÖNEMLİ.",
["Sizi henüz görmediler... Hâlâ sorun yok."] = "SİZİ HENÜZ GÖRMEDİLER... HÂLÂ SORUN YOK.",
["Sizi indirmek için ellerinden geleni yapacaklar!"] = "SİZİ İNDİRMEK İÇİN ELLERİNDEN GELENİ YAPACAKLAR!",
["Sizi izliyorum, sik suratlılar. Bokumu yiyin!"] = "SİZİ İZLİYORUM, SİK SURATLILAR. BOKUMU YİYİN!",
["Sizi kasabanın dışında alırım ama oraya çabuk ve peşinize polis takmadan gelin. Kanalizasyona inin!"] = "SİZİ KASABANIN DIŞINDA ALIRIM AMA ORAYA ÇABUK VE PEŞİNİZE POLİS TAKMADAN GELİN. KANALİZASYONA İNİN!",
["Sizi kim gönderdi piçler? Bildiğin amatörsünüz!"] = "SİZİ KİM GÖNDERDİ PİÇLER? BİLDİĞİN AMATÖRSÜNÜZ!",
["Sizi kim gönderdi? Durun, söylemeyin. Bunu zorla söktürmekten zevk alacağım. Tırnaklarınızı sökmekten alacağım gibi."] = "SİZİ KİM GÖNDERDİ? DURUN, SÖYLEMEYİN. BUNU ZORLA SÖKTÜRMEKTEN ZEVK ALACAĞIM. TIRNAKLARINIZI SÖKMEKTEN ALACAĞIM GİBİ.",
["Sizi kim gönderdi? Sizi kimin gönderdiğini biliyorum!"] = "SİZİ KİM GÖNDERDİ? SİZİ KİMİN GÖNDERDİĞİNİ BİLİYORUM!",
["Sizi kimse görmedi. Öyle kalsın. Şimdi kapıya."] = "SİZİ KİMSE GÖRMEDİ. ÖYLE KALSIN. ŞİMDİ KAPIYA.",
["Sizi kurtarmak zorunda kalmak istemiyorum! Savaşın!"] = "SİZİ KURTARMAK ZORUNDA KALMAK İSTEMİYORUM! SAVAŞIN!",
["Sizi kıstırmalarına izin vermeyin! İlerleyin!"] = "SİZİ KISTIRMALARINA İZİN VERMEYİN! İLERLEYİN!",
["Sizi lanet göt piçler. Bunun için sizi öldüreceğim amına koyayım. Duydunuz mu? Öldüreceğim!"] = "SİZİ LANET GÖT PİÇLER. BUNUN İÇİN SİZİ ÖLDÜRECEĞİM AMINA KOYAYIM. DUYDUNUZ MU? ÖLDÜRECEĞİM!",
["Sizi lanet otuzbirciler, hiç acele etmediniz, değil mi!"] = "SİZİ LANET OTUZBİRCİLER, HİÇ ACELE ETMEDİNİZ, DEĞİL Mİ!",
["Sizi neyin bu kadar geciktirdiğini bilmiyorum ama o kokain sizi BEKLEMİYOR."] = "SİZİ NEYİN BU KADAR GECİKTİRDİĞİNİ BİLMİYORUM AMA O KOKAİN SİZİ BEKLEMİYOR.",
["Sizi o ofisten uzak tutmak için tecritten fazlası gerekir."] = "SİZİ O OFİSTEN UZAK TUTMAK İÇİN TECRİTTEN FAZLASI GEREKİR.",
["Sizi oradan çıkarabilmem için girişe dönmeniz gerekiyor."] = "SİZİ ORADAN ÇIKARABİLMEM İÇİN GİRİŞE DÖNMENİZ GEREKİYOR.",
["Sizi oradan çıkaracağım. Yeter ki ganimeti koruyun!"] = "SİZİ ORADAN ÇIKARACAĞIM. YETER Kİ GANİMETİ KORUYUN!",
["Sizi oradan çıkaralım dostlar."] = "SİZİ ORADAN ÇIKARALIM DOSTLAR.",
["Sizi oradan çıkaralım. Can filikalarından birini kullanın."] = "SİZİ ORADAN ÇIKARALIM. CAN FİLİKALARINDAN BİRİNİ KULLANIN.",
["Sizi oradan çıkarma vakti. Çıkarken alabildiğiniz ganimeti alın."] = "SİZİ ORADAN ÇIKARMA VAKTİ. ÇIKARKEN ALABİLDİĞİNİZ GANİMETİ ALIN.",
["Sizi parça parça keseceğim lan!"] = "SİZİ PARÇA PARÇA KESECEĞİM LAN!",
["Sizi pislikler, işaretlediğiniz kamyon yanlışmış. O oy makinelerinin önünü kesmeyi unutabiliriz. Elephant'ı memnun tutmak için başka bir şey deneyeceğiz. Oy verme yerindeki sunucuyu bozarak seçimin yenilenmesini sağlayabiliriz. Sponsorumuza şüphe çekmemek için yandaki bankayı soyup bunu kazara oluşan bir hasar gibi göstereceğiz."] = "SİZİ PİSLİKLER, İŞARETLEDİĞİNİZ KAMYON YANLIŞMIŞ. O OY MAKİNELERİNİN ÖNÜNÜ KESMEYİ UNUTABİLİRİZ. ELEPHANT'I MEMNUN TUTMAK İÇİN BAŞKA BİR ŞEY DENEYECEĞİZ. OY VERME YERİNDEKİ SUNUCUYU BOZARAK SEÇİMİN YENİLENMESİNİ SAĞLAYABİLİRİZ. SPONSORUMUZA ŞÜPHE ÇEKMEMEK İÇİN YANDAKİ BANKAYI SOYUP BUNU KAZARA OLUŞAN BİR HASAR GİBİ GÖSTERECEĞİZ.",
["Sizi rahatsız etmeyi hiç istemem, gerçekten, ama asıl hedefimiz sandıkları bulmak."] = "SİZİ RAHATSIZ ETMEYİ HİÇ İSTEMEM, GERÇEKTEN, AMA ASIL HEDEFİMİZ SANDIKLARI BULMAK.",
["Sizi rezil Yankee siki çuvalları. Bugün öleceksiniz!"] = "SİZİ REZİL YANKEE SİKİ ÇUVALLARI. BUGÜN ÖLECEKSİNİZ!",
["Sizi rottweiler'larıma yedireceğim. Köpek mamasısınız siz."] = "SİZİ ROTTWEİLER'LARIMA YEDİRECEĞİM. KÖPEK MAMASISINIZ SİZ.",
["Sizi takip ettiğinden emin olun!"] = "SİZİ TAKİP ETTİĞİNDEN EMİN OLUN!",
["Sizi tanımam mı gerekiyor? Kusura bakmayın."] = "SİZİ TANIMAM MI GEREKİYOR? KUSURA BAKMAYIN.",
["Sizi tanıyorum! Bizimle kaç kez yolculuk ettiniz artık?"] = "SİZİ TANIYORUM! BİZİMLE KAÇ KEZ YOLCULUK ETTİNİZ ARTIK?",
["Sizi yakalarsam bu yaptığınız yanınıza kalmaz!"] = "SİZİ YAKALARSAM BU YAPTIĞINIZ YANINIZA KALMAZ!",
