["Sizi çıkarmak için bekleyen bir helikopter var. Ama çağırır çağırmaz ortalık hızla karışacak. O yüzden doğru anı seçin."] = "SİZİ ÇIKARMAK İÇİN BEKLEYEN BİR HELİKOPTER VAR. AMA ÇAĞIRIR ÇAĞIRMAZ ORTALIK HIZLA KARIŞACAK. O YÜZDEN DOĞRU ANI SEÇİN.",
["Sizi öldüreceğim!"] = "SİZİ ÖLDÜRECEĞİM!",
["Sizi öyle tıkılmış görmek hoş değil ama dört kamyon yakaladık. Çıkıp üstlerine gidin!"] = "SİZİ ÖYLE TIKILMIŞ GÖRMEK HOŞ DEĞİL AMA DÖRT KAMYON YAKALADIK. ÇIKIP ÜSTLERİNE GİDİN!",
["Sizi şeker hastası yapacak kadar şekerli tatlımız olduğunu unutmayın."] = "SİZİ ŞEKER HASTASI YAPACAK KADAR ŞEKERLİ TATLIMIZ OLDUĞUNU UNUTMAYIN.",
["Sizi... Sikikler! Okyanusun dibine konteyner içinde bırakacağım!"] = "SİZİ... SİKİKLER! OKYANUSUN DİBİNE KONTEYNER İÇİNDE BIRAKACAĞIM!",
